  tools.exec_command({"cmd":"sed -n '1,240p' docs/design-notes.md && sed -n '1,260p' docs/session-log.md","workdir":"/var/work/repo3/stm/stm","yield_time_ms":10000,"max_output_tokens":30000}),
  tools.exec_command({"cmd":"git status --short && git log --oneline -12","workdir":"/var/work/repo3/stm/stm","yield_time_ms":10000,"max_output_tokens":12000}),
  tools.exec_command({"cmd":"rg -n -i \"events|stream_key|flow_key|event\" fe be --glob '!**/node_modules/**' --glob '!**/dist/**' | head -n 300","workdir":"/var/work/repo3/stm/stm","yield_time_ms":10000,"max_output_tokens":30000}),
  tools.exec_command({"cmd":"rg --files fe | sed -n '1,240p'; rg --files be | sed -n '1,160p'","workdir":"/var/work/repo3/stm/stm","yield_time_ms":10000,"max_output_tokens":30000})
]);
text(r.map(x=>x.output).join("\n\n"));

