};

export type TimelineWindow = {
  from: number;
  to: number;
};

export type ScopeLayer =
  | { kind: "vlan"; id?: string; priority?: string; dei?: string }
  | { kind: "vxlan"; vni?: string };

export type NetworkScope = {
  interfaceId?: number;
  interfaceName?: string;
  known: boolean;
  layers: ScopeLayer[];
};

export type TimelineRow = {
  rowType: "stream" | "flow";
  streamKey: string;
  flowKey?: string;
  parentStreamKey?: string;
  kind: string;
  proto: string;
  label: string;
  role?: string;
  endpointSrc?: string;
  endpointDst?: string;
  interfaceId?: number;
  interfaceName?: string;
  scope?: NetworkScope;
  active: boolean;
  firstSeen: number;
  lastSeen: number;
  segments: TimelineSegment[];
};

export type TimelineViewResponse = {
  rows: TimelineRow[];
  window: TimelineWindow;
  available: TimelineWindow;
  source: "live" | "history";
};

export type FlowListItem = {
  flowKey: string;
  role: string;
  label: string;
  scope: NetworkScope;
  active: boolean;
  interfaceId?: number;
  interfaceName?: string;
  endpointSrc?: string;
  endpointDst?: string;
  lastSeen: number;
  bitrate: NumericStat;
  sparkline: number[];
  overview: OverviewStats;
};

export type StreamListItem = {
  streamKey: string;
  kind: string;
  proto: string;
  label: string;
  scope: NetworkScope;
  endpointA?: string;
  endpointB?: string;
  sessionDst?: string;
