import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { FlowListItem, InterfaceListItem, StreamListItem } from "../types/api";
import { Sparkline } from "./Sparkline";
import { Icon } from "./ui/Icon";
import { formatBitrate, formatRelativeTime } from "./format";

type StreamTableProps = {
  streams: StreamListItem[];
  interfaces: InterfaceListItem[];
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  selectedInterfaceKey: string | null;
  overviewMode?: boolean;
  expandLevel?: "interface" | "proto" | "stream" | "flow";
  onSelectInterface: (interfaceKey: string) => void;
  onSelectStream: (streamKey: string) => void;
  onSelectFlow: (streamKey: string, flowKey: string) => void;
  onAddToDashboard?: (streamKey: string, flowKey?: string) => void;
};

const TOTAL_COLOR = "#66d9ef";
const FLOW_ROLE_COLORS: Record<string, string> = {
  media: "#7fd4c7",
  fec_row: "#62b7c3",
  fec_col: "#6e97c7",
  control: "#5f7fb9",
  mixed: "#6fa7d4",
  default: "#7f98b5"
};
const FLOW_ROLE_LINE_COLORS: Record<string, string> = {
  media: "#9ae2d7",
  fec_row: "#7cc7d1",
  fec_col: "#87abd5",
  control: "#7695cb",
  mixed: "#8bb8de",
  default: "#97acc3"
};
const DONUT_COLORS = ["#66d9ef", "#7fd4c7", "#6e97c7", "#62b7c3", "#8bb8de", "#7f98b5"];
const ENABLE_FLIP_ANIMATION = false;
const ENABLE_SPARKLINES = true;
const ENABLE_OVERVIEW_STATS = true;
const ENABLE_OVERVIEW_CHARTS = false;
const MAX_STREAM_ROWS_PER_GROUP = 200;
const MAX_FLOW_ROWS_PER_STREAM = 80;
const STREAM_TABLE_OVERSCAN_PX = 600;
const STREAM_TABLE_ROW_HEIGHT = { interface: 48, scope: 48, proto: 48, stream: 48, flow: 48, truncated: 32 };

type InterfaceGroup = {
  key: string;
  name: string;
  interfaceItem?: InterfaceListItem;
  streams: StreamListItem[];
};

type ScopeGroup = { key: string; label: string; streams: StreamListItem[] };

type FlatRow =
  | { key: string; type: "interface"; height: number; group: InterfaceGroup }
  | { key: string; type: "scope"; height: number; group: ScopeGroup }
  | { key: string; type: "proto"; height: number; group: { key: string; proto: string; streams: StreamListItem[] } }
  | { key: string; type: "stream"; height: number; stream: StreamListItem }
  | { key: string; type: "flow"; height: number; stream: StreamListItem; flow: FlowListItem }
  | { key: string; type: "truncated"; height: number; label: string; depth: "stream" | "flow" };

export function StreamTable({ streams, interfaces, selectedStreamKey, selectedFlowKey, selectedInterfaceKey, overviewMode = false, expandLevel = "flow", onSelectInterface, onSelectStream, onSelectFlow, onAddToDashboard }: StreamTableProps) {
  const tableRef = useRef<HTMLDivElement>(null);
  const scrollingRef = useRef(false);
  const scrollIdleTimerRef = useRef<number | null>(null);
  const scrollRafRef = useRef<number | null>(null);
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
  const [expandedInterfaces, setExpandedInterfaces] = useState<Set<string>>(() => new Set());
  const [expandedProtoGroups, setExpandedProtoGroups] = useState<Set<string>>(() => new Set());
  const [expandedScopeGroups, setExpandedScopeGroups] = useState<Set<string>>(() => new Set());
  const [viewport, setViewport] = useState({ top: 0, height: 640 });
  const hasAppliedExpandLevel = useRef(false);
  const previousExpandLevel = useRef<typeof expandLevel>(expandLevel);
  const previousRects = useRef(new Map<string, DOMRect>());
  const seenProtoGroupKeys = useRef<Set<string>>(new Set());
  const maxStreamBitrate = useMemo(() => Math.max(...streams.map(streamBitrateOf), 1), [streams]);
  const interfaceGroups = useMemo(() => buildInterfaceGroups(interfaces, streams), [interfaces, streams]);
  const groupedByInterface = interfaceGroups.length > 0;

  useEffect(() => {
    if (hasAppliedExpandLevel.current && previousExpandLevel.current === expandLevel) {
      return;
    }
    previousExpandLevel.current = expandLevel;
    setExpandedInterfaces(expandedInterfaceKeys(interfaceGroups, expandLevel));
    setExpanded(expandedStreamKeys(streams, expandLevel));
    setExpandedScopeGroups(expandedScopeKeys(interfaceGroups, expandLevel));
    setExpandedProtoGroups(expandedProtoKeys(interfaceGroups, streams, expandLevel));
    if (interfaceGroups.length > 0 || streams.length > 0) {
      hasAppliedExpandLevel.current = true;
    }
  }, [expandLevel, interfaceGroups, streams]);

  useEffect(() => {
    if (expandLevel !== "stream" && expandLevel !== "flow") return;
    const keys = protoGroupKeys(interfaceGroups, streams);
    if (keys.length === 0) return;
    setExpandedProtoGroups((current) => {
      const next = new Set(current);
      for (const key of keys) {
        if (!seenProtoGroupKeys.current.has(key)) {
          next.add(key);
          seenProtoGroupKeys.current.add(key);
        }
      }
      return next;
    });
  }, [expandLevel, groupedByInterface, interfaceGroups, streams]);

  useLayoutEffect(() => {
    if (!ENABLE_FLIP_ANIMATION) {
      return;
    }
    const root = tableRef.current;
    if (!root) return;

    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const nodes = Array.from(root.querySelectorAll<HTMLElement>("[data-flip-key]"));
    const disableFlip = !ENABLE_FLIP_ANIMATION || reduceMotion || scrollingRef.current || nodes.length > 220;
    const nextRects = new Map<string, DOMRect>();
    if (!disableFlip) {
      for (const node of nodes) {
        const key = node.dataset.flipKey;
        if (!key) continue;
        nextRects.set(key, node.getBoundingClientRect());
      }
      for (const node of nodes) {
        const key = node.dataset.flipKey;
        if (!key) continue;
        const prev = previousRects.current.get(key);
        const next = nextRects.get(key);
        if (!prev || !next) continue;

        const dx = prev.left - next.left;
        const dy = prev.top - next.top;
        if (Math.abs(dx) < 1 && Math.abs(dy) < 1) continue;

        node.animate(
          [
            { transform: `translate(${dx}px, ${dy}px)`, opacity: 0.55 },
            { transform: "translate(0, 0)", opacity: 1 }
          ],
          {
            duration: 340,
            easing: "cubic-bezier(0.22, 1, 0.36, 1)"
          }
        );
      }
    }

    previousRects.current = nextRects;
  }, [streams, interfaces, groupedByInterface, expandLevel, overviewMode]);

  useEffect(() => {
    return () => {
      if (scrollIdleTimerRef.current !== null) {
        window.clearTimeout(scrollIdleTimerRef.current);
      }
      if (scrollRafRef.current !== null) {
        window.cancelAnimationFrame(scrollRafRef.current);
      }
    };
  }, []);

  useLayoutEffect(() => {
    const root = tableRef.current;
    if (!root) return;

    const update = () => {
      setViewport((current) => {
        const next = { top: root.scrollTop, height: root.clientHeight || 640 };
        return current.top === next.top && current.height === next.height ? current : next;
      });
    };

    update();
    const observer = new ResizeObserver(update);
    observer.observe(root);
    return () => observer.disconnect();
  }, []);

  const selectStream = (stream: StreamListItem) => {
    onSelectStream(stream.streamKey);
  };

  const toggleStream = (streamKey: string) => {
    setExpanded((current) => {
      const next = new Set(current);
      if (next.has(streamKey)) next.delete(streamKey);
      else next.add(streamKey);
      return next;
    });
  };

  const toggleInterface = (key: string) => {
    setExpandedInterfaces((current) => {
      const next = new Set(current);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  };

  const toggleScopeGroup = (key: string) => {
    setExpandedScopeGroups((current) => {
      const next = new Set(current);
      if (next.has(key)) next.delete(key); else next.add(key);
      return next;
    });
  };

  const toggleProtoGroup = (key: string) => {
    setExpandedProtoGroups((current) => {
      const next = new Set(current);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  };

  const flatRows = useMemo(() => {
    const rows: FlatRow[] = [];

    const appendStreamCollection = (collection: StreamListItem[], groupKey: string) => {
      for (const scopeGroup of buildScopeGroups(collection, groupKey)) {
        rows.push({ key: "scope:" + scopeGroup.key, type: "scope", height: STREAM_TABLE_ROW_HEIGHT.scope, group: scopeGroup });
        if (!expandedScopeGroups.has(scopeGroup.key)) continue;
        for (const protoGroup of buildProtoGroups(scopeGroup.streams, scopeGroup.key)) {
          rows.push({ key: "proto:" + protoGroup.key, type: "proto", height: STREAM_TABLE_ROW_HEIGHT.proto, group: protoGroup });
          if (!expandedProtoGroups.has(protoGroup.key)) continue;
          const visibleStreams = protoGroup.streams.slice(0, MAX_STREAM_ROWS_PER_GROUP);
          for (const stream of visibleStreams) {
            rows.push({ key: "stream:" + stream.streamKey, type: "stream", height: STREAM_TABLE_ROW_HEIGHT.stream, stream });
            if (!isExpandable(stream) || !expanded.has(stream.streamKey)) continue;
            for (const flow of stream.flows.slice(0, MAX_FLOW_ROWS_PER_STREAM)) {
              rows.push({ key: "flow:" + stream.streamKey + ":" + flow.flowKey, type: "flow", height: STREAM_TABLE_ROW_HEIGHT.flow, stream, flow });
            }
          }
        }
      }
    };

    if (groupedByInterface) {
      for (const group of interfaceGroups) {
        rows.push({
          key: `interface:${group.key}`,
          type: "interface",
          height: STREAM_TABLE_ROW_HEIGHT.interface,
          group
        });
        if (expandedInterfaces.has(group.key)) {
          appendStreamCollection(group.streams, group.key);
        }
      }
    } else {
      appendStreamCollection(streams, "root");
    }

    return rows;
  }, [expanded, expandedInterfaces, expandedScopeGroups, expandedProtoGroups, groupedByInterface, interfaceGroups, streams]);

  const virtualRows = useMemo(() => {
    const offsets = new Array<number>(flatRows.length);
    let total = 0;
    for (let index = 0; index < flatRows.length; index += 1) {
      offsets[index] = total;
      total += flatRows[index].height;
    }

    const startY = Math.max(0, viewport.top - STREAM_TABLE_OVERSCAN_PX);
    const endY = viewport.top + viewport.height + STREAM_TABLE_OVERSCAN_PX;
    let startIndex = 0;
    while (startIndex < flatRows.length && offsets[startIndex] + flatRows[startIndex].height < startY) {
      startIndex += 1;
    }

    let endIndex = startIndex;
    while (endIndex < flatRows.length && offsets[endIndex] < endY) {
      endIndex += 1;
    }

    const topPad = startIndex > 0 ? offsets[startIndex] : 0;
    const bottomPad = Math.max(0, total - (endIndex > 0 ? offsets[endIndex - 1] + flatRows[endIndex - 1].height : 0));

    return {
      topPad,
      bottomPad,
      visible: flatRows.slice(startIndex, endIndex)
    };
  }, [flatRows, viewport]);

  const stickyContext = useMemo(() => {
    if (viewport.top < STREAM_TABLE_ROW_HEIGHT.interface) return [];
    const labels: string[] = [];
    let consumed = 0;
    for (const row of flatRows) {
      if (consumed > viewport.top) break;
      consumed += row.height;
      if (row.type === "interface") labels.splice(0, labels.length, row.group.name);
      else if (row.type === "scope") labels.splice(1, labels.length - 1, row.group.label);
      else if (row.type === "proto") labels.splice(2, labels.length - 2, row.group.proto);
      else if (row.type === "stream") labels.splice(3, labels.length - 3, streamEndpointLabel(row.stream));
    }
    return labels.length > 1 ? labels : [];
  }, [flatRows, viewport.top]);

  const renderStreamRow = (stream: StreamListItem) => {
    const expandable = isExpandable(stream);
    const opened = expanded.has(stream.streamKey);
    const streamBitrate = streamBitrateOf(stream);

    return (
      <div className="stream-tree stream-tree-virtual" data-flip-key={`stream:${stream.streamKey}`}>
        <div
          role="button"
          tabIndex={0}
          className={`stream-row ${stream.streamKey === selectedStreamKey && !selectedFlowKey ? "selected" : ""}`}
export function formatBitrate(value?: number) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  const units = ["bps", "Kbps", "Mbps", "Gbps"];
  let current = value;
  let unit = 0;
  while (current >= 1000 && unit < units.length - 1) {
    current /= 1000;
    unit += 1;
  }
  return `${current >= 100 ? current.toFixed(0) : current.toFixed(1)} ${units[unit]}`;
}

export function formatNumber(value?: number) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  return Math.abs(value) >= 1000 ? value.toLocaleString(undefined, { maximumFractionDigits: 1 }) : value.toFixed(3).replace(/\.0+$/, "");
}

export function formatRelativeTime(epochSec?: number) {
  if (!epochSec) return "never";
  const diff = Math.max(0, Date.now() / 1000 - epochSec);
  if (diff < 2) return "now";
  if (diff < 60) return `${Math.round(diff)}s ago`;
  return new Date(epochSec * 1000).toLocaleTimeString([], { hour12: false });
}
