function RowActionMenu({ streamKey, flowKey, onAddToDashboard }: { streamKey: string; flowKey?: string; onAddToDashboard?: (streamKey: string, flowKey?: string) => void }) {
  const [opened, setOpened] = useState(false);
  const menuRef = useRef<HTMLSpanElement>(null);
  const detailUrl = flowKey ? detailUrlForFlow(streamKey, flowKey) : detailUrlForStream(streamKey);
  const keyLabel = flowKey ? "Copy flow key" : "Copy stream key";
  const keyValue = flowKey ?? streamKey;

  useEffect(() => {
    if (!opened) return;
    const onPointerDown = (event: PointerEvent) => {
      if (!menuRef.current?.contains(event.target as Node)) setOpened(false);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpened(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [opened]);

  return (
    <span
      ref={menuRef}
      className="row-action-menu"
      onClick={(event) => {
        event.stopPropagation();
      }}
    >
      <button type="button" className="row-action-trigger" aria-label="Open row actions" aria-expanded={opened} onClick={() => setOpened((current) => !current)}>
        <Icon name="more" size={17} />
      </button>
      {opened && <span className="row-action-popup" role="menu" aria-label="Row actions">
        <button type="button" role="menuitem" onClick={() => { setOpened(false); void copyText(detailUrl); }}>Copy detail URL</button>
        <button type="button" role="menuitem" onClick={() => { setOpened(false); void copyText(keyValue); }}>{keyLabel}</button>
        {onAddToDashboard && <button type="button" role="menuitem" onClick={() => { setOpened(false); onAddToDashboard(streamKey, flowKey); }}>Add Detail to Dashboard</button>}
      </span>}
    </span>
  );
}

function OverviewStats({ stats }: { stats: StreamListItem["overview"] }) {
