function detailUrlForStream(streamKey: string) {
  const url = new URL("/view/detail", window.location.origin);
  url.searchParams.set("streamKey", streamKey);
  return url.toString();
}

function detailUrlForFlow(streamKey: string, flowKey: string) {
  const url = new URL("/view/detail", window.location.origin);
  url.searchParams.set("streamKey", streamKey);
  url.searchParams.set("flowKey", flowKey);
