async function copyText(value: string) {
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(value);
      return;
    }
  } catch {
    // Fall through to the textarea fallback for non-secure contexts.
  }

  const textarea = document.createElement("textarea");
  textarea.value = value;
  textarea.style.position = "fixed";
  textarea.style.left = "-9999px";
  textarea.style.top = "0";
  document.body.appendChild(textarea);
  textarea.focus();
  textarea.select();
  try {
    document.execCommand("copy");
  } finally {
    document.body.removeChild(textarea);
  }
}

function buildInterfaceGroups(interfaces: InterfaceListItem[], streams: StreamListItem[]) {
  const interfaceById = new Map(interfaces.filter((item) => item.interfaceId !== undefined).map((item) => [item.interfaceId!, item]));
  const groups = new Map<string, { key: string; name: string; interfaceItem?: InterfaceListItem; streams: StreamListItem[] }>();

  for (const item of interfaces) {
    groups.set(item.key, {
      key: item.key,
      name: item.name,
      interfaceItem: item,
      streams: []
    });
  }

  for (const stream of streams) {
    const item = stream.interfaceId !== undefined ? interfaceById.get(stream.interfaceId) : undefined;
    const key = item ? item.key : stream.interfaceName ? `name:${stream.interfaceName}` : "unknown";
    const name = item?.name ?? stream.interfaceName ?? "Unknown interface";
    const group = groups.get(key) ?? { key, name, interfaceItem: item, streams: [] };
    group.streams.push(stream);
    groups.set(key, group);
  }

  return [...groups.values()]
    .filter((group) => group.streams.length > 0 || group.interfaceItem)
    .sort((a, b) => {
      if (a.key === "unknown") return 1;
      if (b.key === "unknown") return -1;
      return (a.interfaceItem?.interfaceId ?? Number.MAX_SAFE_INTEGER) - (b.interfaceItem?.interfaceId ?? Number.MAX_SAFE_INTEGER) || a.name.localeCompare(b.name);
    });
}

function expandedInterfaceKeys(
  interfaceGroups: Array<{ key: string; name: string; interfaceItem?: InterfaceListItem; streams: StreamListItem[] }>,
  expandLevel: "interface" | "proto" | "stream" | "flow"
) {
  if (expandLevel === "interface") return new Set<string>();
  return new Set(interfaceGroups.map((group) => group.key));
}

function expandedScopeKeys(interfaceGroups: InterfaceGroup[], expandLevel: "interface" | "proto" | "stream" | "flow") {
  if (expandLevel === "interface") return new Set<string>();
  return new Set(interfaceGroups.flatMap((group) => buildScopeGroups(group.streams, group.key).map((scope) => scope.key)));
}

function buildScopeGroups(streams: StreamListItem[], parentKey: string): ScopeGroup[] {
  const groups = new Map<string, ScopeGroup>();
  for (const stream of streams) {
    const scope = stream.scope;
    const first = scope?.layers?.[0];
    const token = !scope?.known ? "unknown" : first?.kind === "vlan" ? "vlan:" + (first.id ?? "unknown") : first?.kind === "vxlan" ? "vxlan:" + (first.vni ?? "unknown") : "untagged";
    const label = !scope?.known ? "Scope unknown" : first?.kind === "vlan" ? "VLAN " + (first.id ?? "unknown") : first?.kind === "vxlan" ? "VXLAN " + (first.vni ?? "unknown") : "Untagged";
    const key = parentKey + "|scope:" + token;
    const group = groups.get(key) ?? { key, label, streams: [] };
    group.streams.push(stream);
    groups.set(key, group);
  }
  return [...groups.values()].sort((a, b) => a.label.localeCompare(b.label));
}

function expandedStreamKeys(streams: StreamListItem[], expandLevel: "interface" | "proto" | "stream" | "flow") {
  if (expandLevel !== "flow") return new Set<string>();
  return new Set(streams.filter(isExpandable).map((stream) => stream.streamKey));
}

function expandedProtoKeys(
  interfaceGroups: Array<{ key: string; name: string; interfaceItem?: InterfaceListItem; streams: StreamListItem[] }>,
  streams: StreamListItem[],
  expandLevel: "interface" | "proto" | "stream" | "flow"
) {
  if (expandLevel === "interface" || expandLevel === "proto") return new Set<string>();
  return new Set(protoGroupKeys(interfaceGroups, streams));
}

function protoGroupKeys(
  interfaceGroups: Array<{ key: string; name: string; interfaceItem?: InterfaceListItem; streams: StreamListItem[] }>,
  streams: StreamListItem[]
) {
  const collections = interfaceGroups.length > 0
    ? interfaceGroups.map((group) => ({ streams: group.streams, key: group.key }))
    : [{ streams, key: "root" }];
  return collections.flatMap((collection) =>
    buildScopeGroups(collection.streams, collection.key).flatMap((scopeGroup) =>
      buildProtoGroups(scopeGroup.streams, scopeGroup.key).map((protoGroup) => protoGroup.key)
    )
  );
import type { EventLogItem } from "./types";

type AnyRecord = Record<string, any>;

export function normalizeEventLine(line: string): EventLogItem | undefined {
  const raw = JSON.parse(line) as AnyRecord;
  const time = Number(raw.time ?? Date.now() / 1000);
  const type = String(raw.type ?? "event");
  const source = raw.source ?? {};
  const detail = raw.detail;
  const streamKey = source.stream_key ? String(source.stream_key) : undefined;
  const flowKey = source.flow_key ? String(source.flow_key) : undefined;
  const proto = source.proto ? String(source.proto) : undefined;
  const interfaceId = interfaceIdFromKey(flowKey) ?? interfaceIdFromKey(streamKey);
  return {
    id: typeof raw.record_id === "string" && raw.record_id ? raw.record_id : `${time}:${type}:${streamKey ?? "system"}:${flowKey ?? ""}`,
    time,
    type,
    level: levelForType(type),
    scope: flowKey ? "flow" : streamKey ? "stream" : "system",
    proto,
    interfaceId,
    streamKey,
    flowKey,
    targetLabel: targetLabel(proto, streamKey, flowKey, detail),
    message: messageForType(type),
    detail
  };
}

function levelForType(type: string): EventLogItem["level"] {
  if (/error|failed|failure/i.test(type)) return "error";
  if (/warn|stale|drop|loss|timeout/i.test(type)) return "warn";
  return "info";
}

function messageForType(type: string) {
  return type
    .split("_")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

function targetLabel(proto?: string, streamKey?: string, flowKey?: string, detail?: AnyRecord) {
  const endpoint = detail?.endpoint;
  if (proto && endpoint?.a && endpoint?.b) return `${proto} ${endpoint.a} ↔ ${endpoint.b}`;
  if (flowKey) return shortKey(flowKey);
  if (streamKey) return shortKey(streamKey);
  return "System";
}

function shortKey(key: string) {
  return key.length > 96 ? `${key.slice(0, 93)}...` : key;
}

function interfaceIdFromKey(key?: string) {
  const match = key?.match(/(?:^|\|)if=(\d+)/);
  return match ? Number(match[1]) : undefined;
}
