export function normalizeTopologyLine(line: string): TopologySnapshot | undefined {
  const parsed = JSON.parse(line) as AnyRecord;
  const time = Number(parsed.time ?? Date.now() / 1000);
  const nodes = Array.isArray(parsed.nodes) ? parsed.nodes : [];
  const edges = Array.isArray(parsed.edges) ? parsed.edges : [];
  if (!Number.isFinite(time)) return undefined;
  return {
    ...parsed,
    time,
    nodes: nodes.filter((node) => typeof node?.id === "string"),
    edges: edges.filter((edge) => typeof edge?.src === "string" && typeof edge?.dst === "string")
  } as TopologySnapshot;
}

export function normalizeInterfacesLine(line: string): NormalizedInterfaceInput[] {
  const parsed = JSON.parse(line) as AnyRecord;
  const time = Number(parsed.time ?? Date.now() / 1000);
  const interfaces = Array.isArray(parsed.interfaces) ? parsed.interfaces : [];
  return interfaces.map((entry, index) => normalizeInterfaceEntry(entry, index, time));
}

export function normalizeStreamsLine(line: string): NormalizedStreamInput[] {
  const parsed = JSON.parse(line) as AnyRecord;
  const time = Number(parsed.time ?? Date.now() / 1000);
  const interfaces = Array.isArray(parsed.interfaces) ? parsed.interfaces : [];
  const streams = Array.isArray(parsed.streams) ? parsed.streams : [];
  const interfaceNames = interfaceNameMap(interfaces);
  return streams.map((entry) => normalizeStreamEntry(entry, time, interfaceNames)).filter(Boolean) as NormalizedStreamInput[];
}

export function normalizeMetricsLine(line: string): NormalizedMetricInput[] {
  const parsed = JSON.parse(line) as AnyRecord;
  const time = Number(parsed.time ?? Date.now() / 1000);
  const metrics = Array.isArray(parsed.metrics) ? parsed.metrics : [];
  return metrics.map((entry) => normalizeMetricEntry(entry, time)).filter(Boolean) as NormalizedMetricInput[];
}

export function normalizeTimelineLine(line: string): NormalizedTimelineInput | undefined {
  const parsed = JSON.parse(line) as AnyRecord;
  const subject = parsed?.subject ?? {};
  const streamKey = String(subject?.stream_key ?? "");
  if (!streamKey) return undefined;

  const proto = String(subject?.proto ?? inferKind(streamKey));
  const time = Number(parsed.time ?? Date.now() / 1000);
  const interfaceId = numericId(subject?.interface_id ?? interfaceIdFromKey(streamKey));
  const scope = normalizeScope(subject?.scope, subject?.vlan, interfaceId);
  const flowKey = typeof subject?.flow_key === "string" ? subject.flow_key : undefined;
  const endpointSrc = typeof subject?.endpoint?.src === "string" ? subject.endpoint.src : undefined;
  const endpointDst = typeof subject?.endpoint?.dst === "string" ? subject.endpoint.dst : undefined;
  const role = typeof subject?.role === "string" ? subject.role : undefined;
  return {
    time,
    kind: String(parsed.kind ?? ""),
    subjectType: String(subject?.type ?? ""),
    streamKey,
    flowKey,
    proto,
    interfaceId,
    interfaceName: undefined,
    scope,
    label: String(
      subject?.type === "flow"
        ? (endpointSrc && endpointDst ? `${role ?? "flow"}: ${endpointSrc} → ${endpointDst}` : role ?? flowKey ?? streamKey)
        : timelineLabel(proto, subject?.endpoint, streamKey)
    ),
    role,
    endpointSrc,
    endpointDst
  };
}

function normalizeInterfaceEntry(entry: AnyRecord, index: number, time: number): NormalizedInterfaceInput {
  const hasMetrics = Boolean(entry?.rx || entry?.tx);
  const rx = normalizeInterfaceCounters(entry?.rx);
  const tx = normalizeInterfaceCounters(entry?.tx);
  const rxRate = normalizeInterfaceRate(entry?.rx?.rate);
  const txRate = normalizeInterfaceRate(entry?.tx?.rate);
  const rxBps = rxRate.bitrateBps ?? statWindow(rx.bytes) * 8;
  const txBps = txRate.bitrateBps ?? statWindow(tx.bytes) * 8;
  const interfaceId = numericId(entry?.interface_id ?? entry?.id);
  const name = String(entry?.name ?? (interfaceId !== undefined ? `if${interfaceId}` : `if${index}`));
  return {
    key: interfaceId !== undefined ? `if:${interfaceId}` : `name:${name}`,
    interfaceId,
    name,
    observed: entry?.observed === true || interfaceId !== undefined,
    available: entry?.available !== false,
    link: normalizeInterfaceLink(entry?.link),
    lastSeen: time,
    rx,
    tx,
    rxRate,
    txRate,
    rxBitrate: { value: rxBps, avg: rxBps, min: rxBps, max: rxBps },
    txBitrate: { value: txBps, avg: txBps, min: txBps, max: txBps },
    rxSparkline: [],
    txSparkline: [],
    hasMetrics
  };
}

function normalizeInterfaceLink(value: AnyRecord | undefined) {
  const speedMbps = finiteNumber(value?.speed_mbps);
  const mtu = finiteNumber(value?.mtu);
  return {
    speedMbps,
    duplex: typeof value?.duplex === "string" ? value.duplex : undefined,
    operstate: typeof value?.operstate === "string" ? value.operstate : undefined,
    carrier: typeof value?.carrier === "boolean" ? value.carrier : undefined,
    mtu,
    mac: typeof value?.mac === "string" ? value.mac : undefined
  };
}

function normalizeInterfaceRate(value: AnyRecord | undefined) {
  return {
    bitrateBps: finiteNumber(value?.bitrate_bps),
    utilization: finiteNumber(value?.utilization),
    headroomBps: finiteNumber(value?.headroom_bps)
  };
}

function normalizeInterfaceCounters(value: AnyRecord | undefined) {
  return {
    bytes: counterStat(value?.bytes),
    packets: counterStat(value?.packets),
    errors: counterStat(value?.errors),
    dropped: counterStat(value?.dropped)
  };
}

function interfaceNameMap(interfaces: AnyRecord[]) {
  const names = new Map<number, string>();
  for (const entry of interfaces) {
    const id = numericId(entry?.interface_id ?? entry?.id);
    if (id !== undefined && entry?.name !== undefined) {
      names.set(id, String(entry.name));
    }
  }
  return names;
}

function counterStat(value: AnyRecord | undefined): NumericStat {
  const current = Number(value?.window ?? value?.value ?? value?.total ?? 0);
  const total = Number(value?.total ?? current);
  return { value: Number.isFinite(current) ? current : 0, avg: Number.isFinite(current) ? current : 0, min: Number.isFinite(current) ? current : 0, max: Number.isFinite(current) ? current : 0, count: Number.isFinite(total) ? total : undefined };
}

function statWindow(stat: NumericStat) {
  return stat.value ?? stat.avg ?? 0;
}

function normalizeStreamEntry(entry: AnyRecord, time: number, interfaceNames: Map<number, string>): NormalizedStreamInput | undefined {
  const proto = String(entry?.proto ?? "OTHER");
  const raw = entry?.stream ?? {};
  const streamKey = String(raw.stream_key ?? entry.stream_key ?? "");
  if (!streamKey) return undefined;
  const interfaceId = numericId(raw.scope?.interface_id ?? raw.interface_id ?? entry.scope?.interface_id ?? entry.interface_id ?? interfaceIdFromKey(streamKey));
  const scopeInterfaceName = typeof raw.scope?.interface_name === "string" ? raw.scope.interface_name : undefined;
  const interfaceName = interfaceId !== undefined ? interfaceNames.get(interfaceId) ?? scopeInterfaceName : scopeInterfaceName;
  const scope = normalizeScope(raw.scope ?? entry.scope, raw.vlan ?? entry.vlan, interfaceId, interfaceName);

  const hasFlows = Array.isArray(raw.flows);
  const rawFlows = hasFlows ? raw.flows : [];
  const flows: FlowState[] = hasFlows
    ? rawFlows.map((flow: AnyRecord) => normalizeFlowState(flow, time, interfaceId, interfaceName, scope))
    : [defaultFlow(streamKey, proto, raw, time, interfaceId, interfaceName, scope)];

  const preferredFlow = flows.find((flow) => flow.role === "media") ?? flows[0];
  const endpointA = stringValue(raw.endpoint?.a) ?? stringValue(raw.endpoint?.src) ?? endpointFromKey(streamKey, "a") ?? preferredFlow?.endpointSrc;
  const endpointB = stringValue(raw.endpoint?.b) ?? stringValue(raw.endpoint?.dst) ?? endpointFromKey(streamKey, "b") ?? endpointFromKey(streamKey, "ep") ?? preferredFlow?.endpointDst;
  const sessionDst = stringValue(raw.session_dst) ?? stringValue(raw.endpoint?.session_dst) ?? endpointFromKey(streamKey, "session_dst");
  const label = proto === "RTP" && sessionDst
    ? `${proto} ${sessionDst}`
    : endpointA && endpointB
      ? `${proto} ${endpointA} ↔ ${endpointB}`
      : streamKey;

  return {
    time,
    stream: {
      streamKey,
      kind: proto,
      proto,
      label,
      scope,
      endpointA,
      endpointB,
      sessionDst,
      streamId: raw.streamid,
      interfaceId,
      interfaceName,
      active: true,
      lastSeen: Number(raw.last_seen ?? time),
      flowCount: flows.length,
      flowRoles: unique(flows.map((flow) => flow.role)),
      bitrate: {},
      sparkline: [],
      flows
    }
  };
}

function normalizeFlowState(flow: AnyRecord, time: number, parentInterfaceId?: number, parentInterfaceName?: string, parentScope?: NetworkScope): FlowState {
  const role = String(flow.role ?? inferRoleFromKey(flow.flow_key) ?? "flow");
  const endpointSrc = flow.endpoint?.src;
  const endpointDst = flow.endpoint?.dst;
  const interfaceId = numericId(flow.scope?.interface_id ?? flow.interface_id ?? interfaceIdFromKey(flow.flow_key)) ?? parentInterfaceId;
  const scopeInterfaceName = typeof flow.scope?.interface_name === "string" ? flow.scope.interface_name : undefined;
  const ownScope = normalizeScope(flow.scope, flow.vlan, interfaceId, scopeInterfaceName ?? parentInterfaceName);
  const scope = ownScope.known ? ownScope : parentScope ?? ownScope;
  return {
    flowKey: String(flow.flow_key),
    role,
    label: endpointSrc && endpointDst ? `${role}: ${endpointSrc} → ${endpointDst}` : role,
    scope,
    active: true,
    interfaceId,
    interfaceName: interfaceId === parentInterfaceId ? parentInterfaceName ?? scopeInterfaceName : scopeInterfaceName,
    endpointSrc,
    endpointDst,
    lastSeen: Number(flow.last_seen ?? time),
    metrics: {}
  };
}

function defaultFlow(streamKey: string, proto: string, raw: AnyRecord, time: number, interfaceId?: number, interfaceName?: string, scope?: NetworkScope): FlowState {
  const endpointSrc = raw.endpoint?.a;
  const endpointDst = raw.endpoint?.b;
  return {
    flowKey: `${streamKey}|flow=default`,
    role: "default",
    label: endpointSrc && endpointDst ? `${proto}: ${endpointSrc} → ${endpointDst}` : "default",
    scope: scope ?? unknownScope(interfaceId, interfaceName),
    active: true,
    interfaceId,
    interfaceName,
    endpointSrc,
    endpointDst,
    lastSeen: Number(raw.last_seen ?? time),
    metrics: {}
  };
}

function stringValue(value: unknown) {
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

function endpointFromKey(key: string, name: string) {
  const prefix = `${name}=`;
  const field = key.split("|").find((part) => part.startsWith(prefix));
  const value = field?.slice(prefix.length);
  return value || undefined;
}

function normalizeScope(value: unknown, legacyVlan: unknown, interfaceId?: number, interfaceName?: string): NetworkScope {
  const raw = isRecord(value) ? value : undefined;
  const hasLegacyVlan = legacyVlan !== undefined;
  const known = raw !== undefined || hasLegacyVlan;
  const resolvedInterfaceId = numericId(raw?.interface_id) ?? interfaceId;
  const resolvedInterfaceName = typeof raw?.interface_name === "string" ? raw.interface_name : interfaceName;
  const layers = Array.isArray(raw?.layers)
    ? raw.layers.map(normalizeScopeLayer).filter((layer): layer is ScopeLayer => layer !== undefined)
    : legacyScopeLayers(raw?.vlan ?? legacyVlan, raw?.vxlan);
  return { interfaceId: resolvedInterfaceId, interfaceName: resolvedInterfaceName, known, layers };
}

function legacyScopeLayers(vlan: unknown, vxlan: unknown) {
  const layers: ScopeLayer[] = [];
  const normalizedVlan = normalizeVlanLayer(vlan);
  if (normalizedVlan) layers.push(normalizedVlan);
  const normalizedVxlan = normalizeVxlanLayer(vxlan);
  if (normalizedVxlan) layers.push(normalizedVxlan);
  return layers;
}

