export type InterfaceMetricsResponse = {
  key: string;
  interfaceId?: number;
  name: string;
  windowSec: number;
  metrics: Record<string, TimeSeriesMetric>;
};

export type TimeSeriesMetric = {
  key: string;
  label: string;
  unit?: string;
  points: MetricPoint[];
};

export type FlowMetricsResponse = {
  flowKey: string;
  role: string;
  label: string;
  endpointSrc?: string;
  endpointDst?: string;
  metrics: Record<string, TimeSeriesMetric>;
};

export type StreamMetricsResponse = {
  streamKey: string;
  windowSec: number;
  streamBitrate: TimeSeriesMetric;
  flows: FlowMetricsResponse[];
  descriptors: MetricDescriptor[];
};

export type EventLogItem = {
  id: string;
  time: number;
  type: string;
  level: "info" | "warn" | "error";
  scope: "system" | "stream" | "flow";
  proto?: string;
  interfaceId?: number;
  streamKey?: string;
  flowKey?: string;
  targetLabel?: string;
  message: string;
  detail?: unknown;
};

export type TopologyAlertSummary = {
  state?: string;
  severity?: string;
  count?: number;
  alerts?: unknown[];
};

export type TopologyNode = {
  id: string;
  type: string;
  label?: string;
  host?: string;
  port?: number;
  transport?: string;
  alert?: TopologyAlertSummary;
  [key: string]: unknown;
};

  const raw = isRecord(value) ? value : undefined;
  const hasLegacyVlan = legacyVlan !== undefined;
  const known = raw !== undefined || hasLegacyVlan;
  const resolvedInterfaceId = numericId(raw?.interface_id) ?? interfaceId;
  const resolvedInterfaceName = typeof raw?.interface_name === "string" ? raw.interface_name : interfaceName;
  const layers = Array.isArray(raw?.layers)
    ? raw.layers.map(normalizeScopeLayer).filter((layer): layer is ScopeLayer => layer !== undefined)
    : legacyScopeLayers(raw?.vlan ?? legacyVlan, raw?.vxlan);
  return { interfaceId: resolvedInterfaceId, interfaceName: resolvedInterfaceName, known, layers };
}

function legacyScopeLayers(vlan: unknown, vxlan: unknown) {
  const layers: ScopeLayer[] = [];
  const normalizedVlan = normalizeVlanLayer(vlan);
  if (normalizedVlan) layers.push(normalizedVlan);
  const normalizedVxlan = normalizeVxlanLayer(vxlan);
  if (normalizedVxlan) layers.push(normalizedVxlan);
  return layers;
}

function normalizeScopeLayer(value: unknown): ScopeLayer | undefined {
  if (!isRecord(value)) return undefined;
  if (value.kind === "vlan") return normalizeVlanLayer(value);
  if (value.kind === "vxlan") return normalizeVxlanLayer(value);
  return undefined;
}

function normalizeVlanLayer(value: unknown): Extract<ScopeLayer, { kind: "vlan" }> | undefined {
  if (!isRecord(value)) return undefined;
  const id = scopeText(value.id);
  const priority = scopeText(value.priority);
  const dei = scopeText(value.dei);
  if (!id && !priority && !dei) return undefined;
  return { kind: "vlan", id, priority, dei };
}

function normalizeVxlanLayer(value: unknown): Extract<ScopeLayer, { kind: "vxlan" }> | undefined {
  if (!isRecord(value)) return undefined;
  const vni = scopeText(value.vni);
  return vni ? { kind: "vxlan", vni } : undefined;
}

function unknownScope(interfaceId?: number, interfaceName?: string): NetworkScope {
  return { interfaceId, interfaceName, known: false, layers: [] };
}

function isRecord(value: unknown): value is AnyRecord {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function scopeText(value: unknown) {
  return typeof value === "string" || typeof value === "number" ? String(value) : undefined;
}

function timelineLabel(proto: string, endpoint: AnyRecord | undefined, streamKey: string) {
  const sessionDst = typeof endpoint?.session_dst === "string" ? endpoint.session_dst : undefined;
  if (proto === "RTP" && sessionDst) return `${proto} ${sessionDst}`;

  const service = typeof endpoint?.service === "string" ? endpoint.service : undefined;
  if (service) return `${proto} ${service}`;

  const a = typeof endpoint?.a === "string" ? endpoint.a : undefined;
  const b = typeof endpoint?.b === "string" ? endpoint.b : undefined;
  if (a && b) return `${proto} ${a} ↔ ${b}`;

  return streamKey;
}

function normalizeMetricEntry(entry: AnyRecord, time: number): NormalizedMetricInput | undefined {
  const proto = String(entry?.proto ?? "OTHER");
  const streamKey = String(entry?.stream_key ?? "");
  if (!streamKey) return undefined;
  if (entry?.flow_key === undefined) return undefined;

  const flowKey = String(entry.flow_key);
  const role = String(entry?.role ?? inferRoleFromKey(flowKey) ?? "default");
  const endpointSrc = entry?.endpoint?.src;
  const endpointDst = entry?.endpoint?.dst;
  const label = endpointSrc && endpointDst ? `${role}: ${endpointSrc} → ${endpointDst}` : `${proto} ${role}`;
  const interfaceId = numericId(entry.scope?.interface_id ?? entry.interface_id ?? interfaceIdFromKey(flowKey) ?? interfaceIdFromKey(streamKey));
  const scope = normalizeScope(entry.scope, entry.vlan, interfaceId);

  return {
    time,
    streamKey,
    flowKey,
    role,
    label,
    interfaceId,
    scope,
    endpointSrc,
    endpointDst,
    metrics: extractMetrics(entry)
  };
}

function extractMetrics(entry: AnyRecord): Record<string, NumericStat> {
  const metrics: Record<string, NumericStat> = {};
  for (const [key, value] of Object.entries(entry)) {
    if (ignoredMetricKeys.has(key)) continue;
    collectMetric(key, value, metrics);
  }
  return metrics;
}

const ignoredMetricKeys = new Set([
  "proto",
  "stream_key",
  "flow_key",
  "endpoint",
  "role",
  "interface_id",
  "scope",
  "vlan",
  "payload_type",
  "ssrc"
]);

function collectMetric(prefix: string, value: unknown, output: Record<string, NumericStat>) {
  if (typeof value === "number" && Number.isFinite(value)) {
    output[prefix] = { value, avg: value, min: value, max: value };
    return;
  }

  if (!value || typeof value !== "object" || Array.isArray(value)) return;
  const record = value as AnyRecord;
  const stat = statFromObject(record);
  if (stat) {
    output[prefix] = stat;
    return;
  }

  for (const [childKey, childValue] of Object.entries(record)) {
    collectMetric(`${prefix}.${childKey}`, childValue, output);
  }
}

function statFromObject(record: AnyRecord): NumericStat | undefined {
  const stat: NumericStat = {};
  const value = firstNumber(record.value, record.bps, record.pps, record.seconds, record.total);
  if (value !== undefined) stat.value = value;
  if (isNumber(record.avg)) stat.avg = record.avg;
  if (isNumber(record.min)) stat.min = record.min;
  if (isNumber(record.max)) stat.max = record.max;
  if (isNumber(record.count)) stat.count = record.count;

