  const destination = row.endpointDst || endpointFromKey(key, "dst");
  if (source && destination) return source + " → " + destination;
  return source || destination || stripProtoPrefix(row.label, row.proto);
}

function endpointFromKey(key: string, field: "src" | "dst" | "ep") {
  return key.match(new RegExp(`(?:^|\\|)${field}=([^|]+)`))?.[1];
}

function stripProtoPrefix(label: string, proto: string) {
  if (!proto || !label.toUpperCase().startsWith(proto.toUpperCase())) return label;
  return label.slice(proto.length).replace(/^[\s:/|_-]+/, "") || label;
}

function formatTimeTravel(epochSec: number) {
  return new Date(epochSec * 1000).toLocaleString(undefined, { hour12: false });
}

function standaloneViewFromPath(pathname: string): StandaloneView {
  switch (pathname.replace(/\/+$/, "")) {
