namespace stream_json {

inline void add_vlan_if_present(json &j, const tsv::vlan_info &vlan) {
	if(vlan.empty() == false) {
		j["vlan"] = tsv::to_json(vlan);
	}
}

inline void add_vlan_or_null(json &j, const tsv::vlan_info &vlan) {
	j["vlan"] = vlan.empty() ? json(nullptr) : tsv::to_json(vlan);
}

inline json make_stream_event_source(std::string_view proto,
                                     std::uint32_t interface_id,
                                     std::string_view interface_name,
                                     std::string_view stream_key,
                                     const tsv::vlan_info &vlan) {
	json j{
		{"proto", std::string(proto)},
		{"interface_id", interface_id},
		{"stream_key", std::string(stream_key)},
		{"scope", tsv::scope_json(interface_id, interface_name, vlan)},
	};
	add_vlan_if_present(j, vlan);
	return j;
}

inline json make_flow_event_source(std::string_view proto,
                                   std::uint32_t interface_id,
                                   std::string_view interface_name,
                                   std::string_view stream_key,
                                   std::string_view flow_key,
                                   const tsv::vlan_info &vlan) {
	json j = make_stream_event_source(proto, interface_id, interface_name, stream_key, vlan);
	j["flow_key"] = std::string(flow_key);
	return j;
}

