  if (isNumber(record.avg)) stat.avg = record.avg;
  if (isNumber(record.min)) stat.min = record.min;
  if (isNumber(record.max)) stat.max = record.max;
  if (isNumber(record.count)) stat.count = record.count;

  if (stat.avg === undefined && stat.value !== undefined) stat.avg = stat.value;
  if (stat.min === undefined && stat.value !== undefined) stat.min = stat.value;
  if (stat.max === undefined && stat.value !== undefined) stat.max = stat.value;

