import { createReadStream, existsSync, readdirSync } from "node:fs";
import path from "node:path";
import readline from "node:readline";
import { config } from "../config";
import { normalizeEventLine } from "../events";
import type { EventLogItem } from "../types";

type QueryOptions = {
  from: number;
  to: number;
  streamKey?: string;
  flowKey?: string;
  interfaceId?: number;
  proto?: string;
  level?: EventLogItem["level"];
  type?: string;
  limit?: number;
};

export async function queryEventsHistory(options: QueryOptions): Promise<EventLogItem[]> {
  const keep = Number.isFinite(options.limit) && (options.limit ?? 0) > 0
    ? Math.floor(options.limit as number)
    : Number.POSITIVE_INFINITY;

  const matched: EventLogItem[] = [];
  const files = listEventFiles(options.from, options.to);
  if (config.eventsQueryDebugLog) {
    console.error(`[EVENTS_QUERY] files=${files.length} from=${options.from} to=${options.to}`);
    for (const file of files) {
      console.error(`[EVENTS_QUERY] file=${file}`);
    }
  }
  let scanned = 0;
  let filtered = 0;

  for (const file of files) {
    let fileScanned = 0;
    let fileMatched = 0;
    const rl = readline.createInterface({
      input: createReadStream(file),
      crlfDelay: Infinity
    });

    for await (const line of rl) {
      scanned += 1;
      fileScanned += 1;
      if (!line) continue;
      let event: EventLogItem | undefined;
      try {
        event = normalizeEventLine(line);
      } catch {
        event = undefined;
      }
      if (!event) continue;
      if (event.time < options.from || event.time > options.to) continue;
      if (options.streamKey && event.streamKey !== options.streamKey) continue;
      if (options.flowKey && event.flowKey !== options.flowKey) continue;
      if (options.interfaceId !== undefined && event.interfaceId !== options.interfaceId) continue;
      if (options.proto && (event.proto ?? "") !== options.proto) continue;
      if (options.level && event.level !== options.level) continue;
      if (options.type && event.type !== options.type) continue;

      filtered += 1;
      fileMatched += 1;
      matched.push(event);
      if (matched.length > keep) {
        matched.shift();
      }
    }
    if (config.eventsQueryDebugLog) {
      console.error(`[EVENTS_QUERY] file_result file=${file} scanned=${fileScanned} matched=${fileMatched}`);
    }
  }

  if (config.eventsQueryDebugLog) {
    console.error(`[EVENTS_QUERY] from=${options.from} to=${options.to} scanned=${scanned} matched=${filtered} returned=${matched.length}`);
  }

  return matched.sort((a, b) => b.time - a.time);
}

function listEventFiles(from: number, to: number) {
  const files: string[] = [];
  const historyRoot = config.eventJournalDir;
  if (existsSync(historyRoot)) {
    const current = new Date(Math.floor(from) * 1000);
    current.setUTCMinutes(0, 0, 0);
    const end = new Date(Math.floor(to) * 1000);
    end.setUTCMinutes(0, 0, 0);

    while (current.getTime() <= end.getTime()) {
      const yyyy = current.getUTCFullYear().toString().padStart(4, "0");
      const mm = String(current.getUTCMonth() + 1).padStart(2, "0");
      const dd = String(current.getUTCDate()).padStart(2, "0");
      const hh = String(current.getUTCHours()).padStart(2, "0");
      const dayDir = path.join(historyRoot, `${yyyy}${mm}${dd}`);
      if (existsSync(dayDir)) {
        const hourFiles = readdirSync(dayDir)
          .filter((name) => new RegExp(`^${hh}(?:\\.part\\d+)?\\.ndjson$`).test(name))
          .sort((a, b) => filePartIndex(a) - filePartIndex(b))
          .map((name) => path.join(dayDir, name));
        files.push(...hourFiles);
      }
      current.setUTCHours(current.getUTCHours() + 1);
    }
  }

  return files;
}

function filePartIndex(name: string) {
  const m = name.match(/\.part(\d+)\.ndjson$/);
  if (!m) return 0;
  return Number(m[1]) || 0;
}
