struct vlan_info {
	std::string id;
	std::string priority;
	std::string dei;

	bool empty() const noexcept {
		return id.empty() && priority.empty() && dei.empty();
	}

	bool operator==(const vlan_info&) const = default;
};

inline void hash_combine_string(std::size_t& seed, const std::string& value) {
	seed ^= std::hash<std::string>{}(value) + 0x9e3779b97f4a7c15ULL + (seed << 6) + (seed >> 2);
}

inline std::size_t hash_value(const vlan_info &vlan) {
	std::size_t h = 0;
	hash_combine_string(h, vlan.id);
	hash_combine_string(h, vlan.priority);
	hash_combine_string(h, vlan.dei);
	return h;
}

inline std::string key_suffix(const vlan_info &vlan) {
	if(vlan.empty()) {
		return {};
	}

	std::string out;
	if(vlan.id.empty() == false) {
		out += "|vlan=" + vlan.id;
	}
	if(vlan.priority.empty() == false) {
		out += "|vlan_pcp=" + vlan.priority;
	}
	if(vlan.dei.empty() == false) {
		out += "|vlan_dei=" + vlan.dei;
	}
	return out;
}

inline json to_json(const vlan_info &vlan) {
	json j = json::object();
	if(vlan.id.empty() == false) {
		j["id"] = vlan.id;
	}
	if(vlan.priority.empty() == false) {
		j["priority"] = vlan.priority;
	}
	if(vlan.dei.empty() == false) {
		j["dei"] = vlan.dei;
	}
	return j;
}

inline json scope_json(std::uint32_t interface_id, std::string_view interface_name, const vlan_info &vlan) {
	return json{
		{"interface_id", interface_id},
		{"interface_name", interface_name.empty() ? json(nullptr) : json(std::string(interface_name))},
		{"vlan", vlan.empty() ? json(nullptr) : to_json(vlan)},
		{"vxlan", nullptr},
	};
}

inline json scope_json(std::uint32_t interface_id, const vlan_info &vlan) {
	return scope_json(interface_id, std::string_view{}, vlan);
}

