  3	type AnyRecord = Record<string, any>;
  4	
  5	export function normalizeEventLine(line: string): EventLogItem | undefined {
  6	  const raw = JSON.parse(line) as AnyRecord;
  7	  const time = Number(raw.time ?? Date.now() / 1000);
  8	  const type = String(raw.type ?? "event");
  9	  const source = raw.source ?? {};
 10	  const detail = raw.detail;
 11	  const streamKey = source.stream_key ? String(source.stream_key) : undefined;
 12	  const flowKey = source.flow_key ? String(source.flow_key) : undefined;
