 14	  const interfaceId = interfaceIdFromKey(flowKey) ?? interfaceIdFromKey(streamKey);
 15	  return {
 16	    id: typeof raw.record_id === "string" && raw.record_id ? raw.record_id : `${time}:${type}:${streamKey ?? "system"}:${flowKey ?? ""}`,
 17	    time,
 18	    type,
 19	    level: levelForType(type),
 20	    scope: flowKey ? "flow" : streamKey ? "stream" : "system",
 21	    proto,
 22	    interfaceId,
 23	    streamKey,
 24	    flowKey,
 25	    targetLabel: targetLabel(proto, streamKey, flowKey, detail),
 26	    message: messageForType(type),
 27	    detail
 28	  };
 29	}
