 31	function levelForType(type: string): EventLogItem["level"] {
 32	  if (/error|failed|failure/i.test(type)) return "error";
 33	  if (/warn|stale|drop|loss|timeout/i.test(type)) return "warn";
 34	  return "info";
 35	}
