  color: var(--text-strong);
  font-size: var(--font-size-sm);
}

.event-context-header button {
  min-height: 22px;
  width: 22px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 18px;
}

.event-context dl {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  gap: 4px var(--space-2);
