import { useLayoutEffect, useRef, useState } from "react";
import type { EventLogItem } from "../types/api";
import { SearchInput } from "./ui/SearchInput";
import { Icon } from "./ui/Icon";
import { matchesSearch } from "./search";

const MAX_RENDERED_EVENTS = 8000;

type EventLogProps = {
  events: EventLogItem[];
  eventsRange: string;
  onChangeEventsRange: (value: string) => void;
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  selectedInterfaceId: number | null;
  initialQuery?: string;
  query?: string;
  onChangeQuery?: (value: string) => void;
  showSearch?: boolean;
  tab?: EventLogTab;
  onChangeTab?: (tab: EventLogTab) => void;
  showHeader?: boolean;
  selectedTimeSec?: number | null;
  onSelectTime?: (timeSec: number) => void;
};

export type EventLogTab = "all" | "selected";

export function EventLog({
  events,
  eventsRange,
  onChangeEventsRange,
  selectedStreamKey,
  selectedFlowKey,
  selectedInterfaceId,
  initialQuery = "",
  query: controlledQuery,
  onChangeQuery,
  showSearch = true,
  tab: controlledTab,
  onChangeTab,
  showHeader = true,
  selectedTimeSec = null,
  onSelectTime
}: EventLogProps) {
  const [internalTab, setInternalTab] = useState<EventLogTab>("all");
  const [internalQuery, setInternalQuery] = useState(initialQuery);
  const tab = controlledTab ?? internalTab;
  const setTab = onChangeTab ?? setInternalTab;
  const query = controlledQuery ?? internalQuery;
  const setQuery = onChangeQuery ?? setInternalQuery;
  const [selectedEvent, setSelectedEvent] = useState<EventLogItem | null>(null);
  const listRef = useRef<HTMLDivElement | null>(null);
  const scrollSnapshotRef = useRef({ top: 0, height: 0 });
  const followLatestRef = useRef(true);
  const eventRowRefs = useRef(new Map<string, HTMLButtonElement>());
  const lastAutoScrolledKeyRef = useRef<string | null>(null);
  const scopedEvents = tab === "all" ? events : events.filter((event) => {
    if (selectedFlowKey) return event.flowKey === selectedFlowKey || event.streamKey === selectedStreamKey;
    if (selectedStreamKey) return event.streamKey === selectedStreamKey;
    if (selectedInterfaceId !== null) return event.interfaceId === selectedInterfaceId;
    return false;
  });
  const normalizedQuery = query.trim();
  const visibleEvents = normalizedQuery ? scopedEvents.filter((event) => eventMatches(event, query)) : scopedEvents;
  const renderedEvents = visibleEvents.slice(0, MAX_RENDERED_EVENTS);
  const visibleSignature = `${visibleEvents[0]?.id ?? ""}:${visibleEvents.length}:${visibleEvents[visibleEvents.length - 1]?.id ?? ""}`;

  useLayoutEffect(() => {
    const element = listRef.current;
    if (!element || visibleEvents.length === 0) return;
    const prev = scrollSnapshotRef.current;
    const heightDelta = element.scrollHeight - prev.height;
    if (!followLatestRef.current && heightDelta !== 0) element.scrollTop = prev.top + heightDelta;
    scrollSnapshotRef.current = { top: element.scrollTop, height: element.scrollHeight };
  }, [visibleSignature, tab, normalizedQuery, eventsRange, visibleEvents.length]);

  useLayoutEffect(() => {
    if (selectedTimeSec === null) {
      lastAutoScrolledKeyRef.current = null;
      return;
    }

    const selected = renderedEvents.reduce<EventLogItem | null>((closest, event) => {
      const distance = Math.abs(event.time - selectedTimeSec);
      if (distance >= 0.5) return closest;
      if (!closest || distance < Math.abs(closest.time - selectedTimeSec)) return event;
      return closest;
    }, null);
    if (!selected) return;
    const scrollKey = selected.id + ":" + visibleSignature;
    if (lastAutoScrolledKeyRef.current === scrollKey) return;

    const frame = window.requestAnimationFrame(() => {
      const row = eventRowRefs.current.get(selected.id);
      const list = listRef.current;
      if (!row || !list) return;

      followLatestRef.current = false;
      const top = Math.max(0, list.scrollTop + row.getBoundingClientRect().top - list.getBoundingClientRect().top - 4);
      list.scrollTop = top;
      scrollSnapshotRef.current = { top: list.scrollTop, height: list.scrollHeight };
      lastAutoScrolledKeyRef.current = scrollKey;
    });
    return () => window.cancelAnimationFrame(frame);
  }, [selectedTimeSec, visibleSignature, renderedEvents.length]);

  const selectEvent = (event: EventLogItem) => {
    setSelectedEvent(event);
    onSelectTime?.(event.time);
  };

  return (
    <section className={`events-card ${showHeader ? "" : "events-card-embedded"}`}>
      {showHeader && (
        <div className="pane-header events-header">
        <div className="pane-header-title-with-icon"><Icon className="pane-header-icon" name="events" size={14} /><h3>Events</h3></div>
        <div className="events-actions">
          {showSearch && <SearchInput className="event-search" value={query} onChange={setQuery} placeholder="Search events" label="event search" />}
          <label className="detail-range-select" title="Event range">
            <span>Range</span>
            <select value={eventsRange} onChange={(event) => onChangeEventsRange(event.target.value)}>
              <option value="24h">24h</option>
              <option value="12h">12h</option>
              <option value="6h">6h</option>
              <option value="3h">3h</option>
              <option value="1h">1h</option>
              <option value="30m">30m</option>
              <option value="10m">10m</option>
              <option value="5m">5m</option>
            </select>
          </label>
          <div className="events-tabs">
            <button className={tab === "all" ? "active" : ""} onClick={() => setTab("all")}>All</button>
            <button className={tab === "selected" ? "active" : ""} onClick={() => setTab("selected")}>Selected</button>
          </div>
        </div>
      </div>
      )}
        <div className={`events-content ${selectedEvent ? "has-context" : ""}`}>
          <div
            ref={listRef}
            className="events-list"
            onScroll={(event) => {
              const element = event.currentTarget;
              followLatestRef.current = element.scrollTop <= 8;
              scrollSnapshotRef.current = { top: element.scrollTop, height: element.scrollHeight };
            }}
          >
            {renderedEvents.length === 0 ? (
              <div className="events-empty">No events</div>
            ) : (
              <>
                {visibleEvents.length > MAX_RENDERED_EVENTS && <div className="events-empty">Showing latest {MAX_RENDERED_EVENTS} / {visibleEvents.length} events</div>}
                {renderedEvents.map((event) => (
                  <EventRow
                    key={event.id}
                    event={event}
                    selected={selectedEvent?.id === event.id || (selectedTimeSec !== null && Math.abs(event.time - selectedTimeSec) < 0.5)}
                    onSelect={() => selectEvent(event)}
                    eventRef={(element) => {
                      if (element) eventRowRefs.current.set(event.id, element);
                      else eventRowRefs.current.delete(event.id);
                    }}
                  />
                ))}
              </>
            )}
          </div>
          {selectedEvent && <EventContext event={selectedEvent} onClose={() => setSelectedEvent(null)} />}
        </div>
    </section>
  );
}

function EventRow({ event, selected, onSelect, eventRef }: { event: EventLogItem; selected: boolean; onSelect: () => void; eventRef: (element: HTMLButtonElement | null) => void }) {
  return (
    <button ref={eventRef} type="button" className={`event-row ${event.level} ${selected ? "time-selected" : ""}`} onClick={onSelect} title="Inspect this event at its timestamp">
      <time className="event-time" dateTime={new Date(event.time * 1000).toISOString()}>{formatEventTime(event.time)}</time>
      <span className="event-level">{event.level}</span>
      <span className="event-target">{event.targetLabel ?? event.proto ?? event.scope}</span>
      <span className="event-message">{event.message}</span>
    </button>
  );
}

function EventContext({ event, onClose }: { event: EventLogItem; onClose: () => void }) {
  return (
    <aside className="event-context" aria-label="Selected event detail">
      <div className="event-context-header">
        <strong>Event detail</strong>
        <button type="button" onClick={onClose} aria-label="Close event detail" title="Close event detail"><Icon name="close" size={16} /></button>
      </div>
      <dl>
        <dt>Time</dt><dd>{formatEventTime(event.time)}</dd>
        <dt>Level</dt><dd>{event.level}</dd>
        <dt>Type</dt><dd>{event.type}</dd>
        <dt>Target</dt><dd>{event.targetLabel ?? event.proto ?? event.scope}</dd>
      </dl>
      <p>{event.message}</p>
      {event.detail !== undefined && <pre>{JSON.stringify(event.detail, null, 2)}</pre>}
    </aside>
  );
}

function formatEventTime(epochSec: number) {
  const date = new Date(epochSec * 1000);
  const pad = (value: number, width = 2) => String(value).padStart(width, "0");
  return `${date.getFullYear()}/${pad(date.getMonth() + 1)}/${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}.${pad(date.getMilliseconds(), 3)}`;
}

function eventMatches(event: EventLogItem, query: string) {
  return matchesSearch([
    formatEventTime(event.time), event.level, event.type, event.scope, event.proto,
    event.interfaceId, event.streamKey, event.flowKey, event.targetLabel, event.message
  ], query);
}

