function percent(value: number, start: number, end: number) {
  return ((value - start) / Math.max(1e-6, end - start)) * 100;
}

function clampPercent(value: number) {
  return Math.min(99.5, Math.max(0.5, value));
}

function formatTick(value: number, spanSec: number) {
  return new Date(value * 1000).toLocaleTimeString([], {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: spanSec <= 600 ? "2-digit" : undefined
  });
}

function formatCursor(value: number) {
  return new Date(value * 1000).toLocaleString([], {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    year: "numeric",
    month: "2-digit",
