  min-width: 0;
  margin: 0;
  padding: 0 var(--space-2);
  border-bottom: 1px solid var(--line);
}

.events-header h3 {
  flex: 0 0 auto;
}

.events-actions {
  gap: 6px;
}

.event-search {
  width: min(260px, 30vw);
}

.events-tabs button {
  min-width: 48px;
  min-height: 24px;
  padding: 0 7px;
  font-size: var(--font-size-xs);
}

.events-content {
  min-height: 0;
  display: grid;
  grid-template-rows: minmax(0, 1fr);
}

.events-content.has-context {
  grid-template-rows: minmax(0, 1fr) minmax(138px, auto);
}

.events-list {
  min-height: 0;
  max-height: none;
  gap: 0;
  padding: var(--space-1);
  background: var(--surface);
}

.event-row {
  min-height: 30px;
  height: 30px;
  grid-template-columns: minmax(0, 180px) minmax(0, 42px) minmax(0, .8fr) minmax(0, 1.8fr);
  column-gap: 4px;
  row-gap: 0;
  padding: 0 var(--space-2);
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 72%, transparent);
  border-radius: 0;
  background: transparent;
  color: var(--text);
  font-size: var(--font-size-xs);
}

.event-time, .event-level, .event-target, .event-message {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.event-row:hover {
  background: var(--surface-muted);
}

.event-row.time-selected {
  background: var(--accent-soft);
  box-shadow: inset 3px 0 0 var(--accent);
}

.event-time {
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.event-level {
  width: fit-content;
  padding: 2px 4px;
  border-radius: var(--radius-sm);
  background: var(--success-soft);
  color: var(--success);
  font-size: 10px;
  line-height: 1;
}

.event-row.warn .event-level {
  background: var(--warning-soft);
  color: var(--warning);
}

.event-row.error .event-level {
  background: var(--danger-soft);
  color: var(--danger);
}

.event-context {
  min-height: 0;
  padding: var(--space-2) var(--space-3);
  border-top: 1px solid var(--line);
  background: var(--surface-muted);
  overflow: auto;
}

.event-context-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  margin-bottom: var(--space-2);
}

.event-context-header strong {
  color: var(--text-strong);
  font-size: var(--font-size-sm);
}

.event-context-header button {
  min-height: 22px;
  width: 22px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 18px;
}

.event-context dl {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  gap: 4px var(--space-2);
  margin: 0;
  font-size: var(--font-size-xs);
}

.event-context dt { color: var(--muted); }
.event-context dd { min-width: 0; margin: 0; overflow-wrap: anywhere; color: var(--text-strong); }
.event-context p { margin: var(--space-2) 0; font-size: var(--font-size-sm); }
.event-context pre { margin: 0; color: var(--muted); font: 11px/1.35 ui-monospace, SFMono-Regular, Menlo, monospace; white-space: pre-wrap; overflow-wrap: anywhere; }

@media (min-width: 1100px) {
  .standalone-events .events-content.has-context {
    grid-template-columns: minmax(0, 1fr) minmax(260px, 320px);
    grid-template-rows: minmax(0, 1fr);
  }

  .standalone-events .event-context {
    border-top: 0;
    border-left: 1px solid var(--line);
  }
}

@media (max-width: 720px) {
  .events-header { align-items: center; }
  .event-search { width: min(160px, 40vw); }
  .events-tabs { display: none; }
  .event-row { grid-template-columns: 145px 42px minmax(0, 1fr); }
  .event-message { display: none; }
}

