    if (cell.viewType === "detail") {
      const mode = dashboardDetailMode(cell);
      const target = dashboardDetailTarget(cell);
      const selectedTarget = target.mode === "pinned" ? target : dashboardSelection;
      const targetLabel = selectedTarget ? dashboardTargetLabel(selectedTarget, streams) : "Select target";
      return <>
        <button type="button" className={"dashboard-detail-target " + target.mode} onClick={() => openDashboardTargetPicker(cell.id, target.mode)} disabled={target.mode === "pinned" && !dashboardEditing} title={target.mode === "pinned" && !dashboardEditing ? "Edit the layout to change this fixed target" : "Select Inspector target"}>
          <Icon name={target.mode === "pinned" ? "targetPinned" : "targetFollow"} size={13} />
          <span>{target.mode === "pinned" ? "Pinned" : "Follow"}</span><span className="dashboard-detail-target-label">{targetLabel}</span>
        </button>
        {dashboardEditing && <button type="button" className="dashboard-detail-target-mode" onClick={() => target.mode === "pinned" ? updateDashboardCellParams(cell.id, { detailTargetMode: "follow", targetStreamKey: "", targetFlowKey: "" }) : openDashboardTargetPicker(cell.id, "pinned")}>
          {target.mode === "pinned" ? "Follow" : "Pin"}
        </button>}
        <div className="detail-mode-tabs" role="tablist" aria-label="Inspector mode">
          <button type="button" className={mode === "overview" ? "active" : ""} onClick={() => updateDashboardCellParams(cell.id, { detailMode: "overview" })}>Overview</button>
          <button type="button" className={mode === "detail" ? "active" : ""} onClick={() => updateDashboardCellParams(cell.id, { detailMode: "detail" })}>Metrics</button>
        </div>
      </>;
    }
    if (cell.viewType === "events") {
      const tab = dashboardEventsTab(cell);
      return <>
        <SearchInput className="dashboard-cell-search" value={query} onChange={(value) => updateDashboardCellParams(cell.id, { query: value })} placeholder="Search events" label="search events" />
        <div className="events-tabs" role="tablist" aria-label="Event scope">
          <button type="button" className={tab === "all" ? "active" : ""} onClick={() => updateDashboardCellParams(cell.id, { eventsTab: "all" })}>All</button>
          <button type="button" className={tab === "selected" ? "active" : ""} onClick={() => updateDashboardCellParams(cell.id, { eventsTab: "selected" })}>Selected</button>
        </div>
      </>;
    }
    return null;
  };

  const addDashboardCell = () => {
    const id = `cell-${Date.now().toString(36)}`;
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => layouts.map((layout) => {
      if (layout.id !== dashboardLayout.id) return layout;
      const cell = { id, title: "Topology", viewType: "topology" as DashboardViewType, grid: { x: 0, y: nextDashboardY(layout.cells), w: 8, h: 8 } };
      const responsiveLayouts = layout.layouts ? Object.fromEntries(
        (Object.entries(layout.layouts) as [DashboardBreakpoint, DashboardCell[]][]).map(([breakpoint, cells]) => {
          const columns = breakpoint === "mobile" ? 4 : breakpoint === "tablet" ? 12 : 24;
          return [breakpoint, [...cells, { ...cell, grid: { x: 0, y: nextDashboardY(cells), w: Math.min(cell.grid.w, columns), h: cell.grid.h } }]];
        })
      ) as DashboardResponsiveLayouts : undefined;
      return { ...layout, cells: [...layout.cells, cell], layouts: responsiveLayouts };
    }));
  };

  const addDashboardDetailCell = (streamKey: string, flowKey?: string) => {
    const stream = streams.find((item) => item.streamKey === streamKey);
    const flow = flowKey ? stream?.flows.find((item) => item.flowKey === flowKey) : undefined;
    const targetLabel = flow
      ? `${flow.endpointSrc ?? "Unknown endpoint"} ⟶ ${flow.endpointDst ?? "Unknown endpoint"}`
      : stream ? streamEndpointLabel(stream) : streamKey;
    const id = `detail-${Date.now().toString(36)}`;
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => layouts.map((layout) => {
      if (layout.id !== dashboardLayout.id) return layout;
      const cell: DashboardCell = {
        id,
        title: `Inspector · ${targetLabel}`,
        viewType: "detail",
        grid: { x: 0, y: nextDashboardY(layout.cells), w: 8, h: 11 },
        params: { detailTargetMode: "pinned", targetStreamKey: streamKey, ...(flowKey ? { targetFlowKey: flowKey } : {}), detailMode: "overview" }
      };
      const responsiveLayouts = layout.layouts ? Object.fromEntries(
        (Object.entries(layout.layouts) as [DashboardBreakpoint, DashboardCell[]][]).map(([breakpoint, cells]) => {
          const columns = breakpoint === "mobile" ? 4 : breakpoint === "tablet" ? 12 : 24;
          return [breakpoint, [...cells, { ...cell, grid: { x: 0, y: nextDashboardY(cells), w: Math.min(cell.grid.w, columns), h: cell.grid.h } }]];
        })
      ) as DashboardResponsiveLayouts : undefined;
      return { ...layout, cells: [...layout.cells, cell], layouts: responsiveLayouts };
    }));
    setActiveTab("dashboard");
    setDashboardEditing(true);
  };

  const removeDashboardCell = (cellId: string) => {
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => layouts.map((layout) => layout.id !== dashboardLayout.id ? layout : {
      ...layout,
      cells: layout.cells.filter((cell) => cell.id !== cellId),
      layouts: layout.layouts ? Object.fromEntries(
        Object.entries(layout.layouts).map(([breakpoint, cells]) => [breakpoint, cells.filter((cell) => cell.id !== cellId)])
      ) as DashboardResponsiveLayouts : undefined
    }));
  };

  const resetDashboardLayout = () => {
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => {
      const retained = layouts.filter((layout) => layout.id !== DEFAULT_DASHBOARD_LAYOUT.id);
      return [DEFAULT_DASHBOARD_LAYOUT, ...retained];
    });
    setDashboardLayoutId(DEFAULT_DASHBOARD_LAYOUT.id);
  };

  const saveDashboardLayout = async () => {
    setDashboardSaveState("saving");
    try {
      const saved = await saveDashboardLayouts(dashboardLayouts);
      setDashboardLayouts(saved.length > 0 ? saved : [DEFAULT_DASHBOARD_LAYOUT]);
      setDashboardSaveState("saved");
    } catch {
      setDashboardSaveState("error");
    }
  };

  const updateDashboardLayouts = (nextLayouts: DashboardResponsiveLayouts) => {
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => layouts.map((layout) => {
      if (layout.id !== dashboardLayout.id) return layout;
      const desktop = nextLayouts.desktop ?? layout.cells;
      return { ...layout, cells: desktop, layouts: nextLayouts };
    }));
  };

  const renderDashboardView = () => (
    <section className="main-tab-view dashboard-view">
      <PaneHeader
        className="dashboard-toolbar"
        icon="dashboard"
        title="Dashboard"
        meta={dashboardContextLabel + " · " + dashboardLayout.cells.length + " cells / " + dashboardLayout.columns + " columns"}
        actions={<div className="dashboard-actions">
          <label className="detail-range-select dashboard-time-range">
            <span>Range</span>
            <select value={dashboardRange} onChange={(event) => setDashboardRange(event.target.value)}>
              {RANGE_OPTIONS.map((range) => <option key={range} value={range}>{range}</option>)}
            </select>
          </label>
          <label className="detail-range-select">
            <span>Layout</span>
            <select value={dashboardLayout.id} onChange={(event) => setDashboardLayoutId(event.target.value)}>
              {dashboardLayouts.map((layout) => <option key={layout.id} value={layout.id}>{layout.name}</option>)}
            </select>
          </label>
          <button type="button" className={`dashboard-action-button button-with-icon ${dashboardEditing ? "primary" : ""}`} onClick={() => setDashboardEditing((editing) => !editing)}>
            {dashboardEditing ? <><Icon name="done" size={15} />Done</> : <><Icon name="edit" size={15} />Edit layout</>}
          </button>
          {dashboardEditing && <>
            <button type="button" className="dashboard-action-button button-with-icon" onClick={addDashboardCell}><Icon name="add" size={15} />Add cell</button>
            <button type="button" className="dashboard-action-button button-with-icon" onClick={resetDashboardLayout}><Icon name="reset" size={15} />Reset</button>
            <button type="button" className="dashboard-action-button button-with-icon primary" onClick={() => void saveDashboardLayout()} disabled={dashboardSaveState === "saving"}>
              <Icon name={dashboardSaveState === "saved" ? "done" : "save"} size={15} />{dashboardSaveState === "saving" ? "Saving" : dashboardSaveState === "saved" ? "Saved" : dashboardSaveState === "error" ? "Retry save" : "Save"}
            </button>
          </>}
        </div>}
      />
      <div className="dashboard-pane-body">
        <DashboardGrid
          dashboard={dashboardLayout}
          editing={dashboardEditing}
          renderCell={renderDashboardCellContent}
          renderCellActions={renderDashboardCellActions}
          onLayoutsChange={updateDashboardLayouts}
          onUpdateCell={updateDashboardCell}
          onRemoveCell={removeDashboardCell}
        />
      </div>
      <DashboardTargetDrawer
        open={dashboardTargetPicker !== null}
        streams={streams}
        interfaces={interfaces}
        selectedStreamKey={dashboardSelectedStreamKey}
        selectedFlowKey={dashboardSelectedFlowKey}
        onClose={() => setDashboardTargetPicker(null)}
        onSelectStream={(streamKey) => {
          if (dashboardTargetPicker?.mode === "pinned") updateDashboardCellParams(dashboardTargetPicker.cellId, { detailTargetMode: "pinned", targetStreamKey: streamKey, targetFlowKey: "" });
          else selectDashboardStream(streamKey);
          setDashboardTargetPicker(null);
        }}
        onSelectFlow={(streamKey, flowKey) => {
          if (dashboardTargetPicker?.mode === "pinned") updateDashboardCellParams(dashboardTargetPicker.cellId, { detailTargetMode: "pinned", targetStreamKey: streamKey, targetFlowKey: flowKey });
          else selectDashboardFlow(streamKey, flowKey);
          setDashboardTargetPicker(null);
        }}
      />
    </section>
  );

  const renderDashboardCellContent = (cell: DashboardCell) => {
    const viewType = cell.viewType;
    if (viewType === "streams") {
      return <StreamTable
        streams={filterStreams(streams, dashboardCellTextParam(cell, "query"))}
        interfaces={interfaces}
        selectedStreamKey={dashboardSelectedStreamKey}
        selectedFlowKey={dashboardSelectedFlowKey}
        selectedInterfaceKey={null}
        overviewMode
        expandLevel={expandLevel}
        onSelectInterface={() => setDashboardSelection(null)}
        onSelectStream={selectDashboardStream}
        onSelectFlow={selectDashboardFlow}
        onAddToDashboard={addDashboardDetailCell}
      />;
    }
    if (viewType === "detail") {
      const target = dashboardDetailTarget(cell);
      const selectedTarget = target.mode === "pinned" ? target : dashboardSelection;
      if (selectedTarget) {
        const snapshot = streams.find((item) => item.streamKey === selectedTarget.streamKey) ?? null;
        return <PinnedDetailPane
          streamKey={selectedTarget.streamKey}
          flowKey={selectedTarget.flowKey}
          snapshotStream={dashboardContextTimeSec !== null && snapshot ? streamListItemToState(snapshot) : null}
          selectedTimeSec={dashboardContextTimeSec}
          metricsRange={dashboardRange}
          mode={dashboardDetailMode(cell)}
          onChangeMode={(mode) => updateDashboardCellParams(cell.id, { detailMode: mode })}
          onChangeMetricsRange={setDashboardRange}
        />;
      }
      return <DashboardDetailEmptyState onChoose={() => openDashboardTargetPicker(cell.id, "follow")} />;
    }
