  text-overflow: ellipsis;
  white-space: nowrap;
}

.event-row:hover {
  background: var(--surface-muted);
}

.event-row.time-selected {
  background: var(--accent-soft);
  box-shadow: inset 3px 0 0 var(--accent);
}

.event-time {
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

