  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  margin-bottom: var(--space-2);
}

.event-context-header strong {
  color: var(--text-strong);
  font-size: var(--font-size-sm);
}

.event-context-header button {
  min-height: 22px;
  width: 22px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--muted);
