  margin: 0;
  font-size: var(--font-size-xs);
}

.event-context dt { color: var(--muted); }
.event-context dd { min-width: 0; margin: 0; overflow-wrap: anywhere; color: var(--text-strong); }
.event-context p { margin: var(--space-2) 0; font-size: var(--font-size-sm); }
