import { Responsive, useContainerWidth, noCompactor, type Compactor, type Layout, type LayoutItem } from "react-grid-layout";
import { useCallback, useMemo, useState, type ReactNode, type Ref } from "react";
import { Icon, type IconName } from "./ui/Icon";
import type { DashboardBreakpoint, DashboardCell, DashboardLayout, DashboardResponsiveLayouts } from "../types/api";

const fixedGridCompactor: Compactor = {
  ...noCompactor,
  preventCollision: true
};

const dashboardViewIcons: Record<DashboardCell["viewType"], IconName> = {
  streams: "streams",
  detail: "detail",
  timeline: "timeline",
  topology: "topology",
  events: "events"
};

type DashboardGridProps = {
  dashboard: DashboardLayout;
  editing: boolean;
  renderCell: (cell: DashboardCell) => ReactNode;
  renderCellActions?: (cell: DashboardCell, editing: boolean) => ReactNode;
  onLayoutsChange: (layouts: DashboardResponsiveLayouts) => void;
  onUpdateCell: (cellId: string, updater: (cell: DashboardCell) => DashboardCell) => void;
  onRemoveCell: (cellId: string) => void;
};

export function DashboardGrid({
  dashboard,
  editing,
  renderCell,
  renderCellActions,
  onLayoutsChange,
  onUpdateCell,
  onRemoveCell
}: DashboardGridProps) {
  const { width, containerRef, mounted } = useContainerWidth({ initialWidth: 1280 });
  const [activeBreakpoint, setActiveBreakpoint] = useState<DashboardBreakpoint>(breakpointForWidth(width));
  const cellsByBreakpoint = useMemo(() => buildResponsiveCells(dashboard.cells, dashboard.layouts), [dashboard.cells, dashboard.layouts]);
  const activeCells = cellsByBreakpoint[activeBreakpoint] ?? dashboard.cells;
  const layouts = useMemo(() => Object.fromEntries(
    (Object.keys(BREAKPOINT_COLUMNS) as DashboardBreakpoint[]).map((breakpoint) => [
      breakpoint,
      cellsByBreakpoint[breakpoint].map(toLayoutItem)
    ])
  ) as unknown as Record<DashboardBreakpoint, Layout>, [cellsByBreakpoint]);

  const handleLayoutChange = useCallback((_layout: Layout, nextLayouts: Partial<Record<string, Layout>>) => {
    if (!editing) return;
    const normalized = {} as DashboardResponsiveLayouts;
    for (const breakpoint of Object.keys(BREAKPOINT_COLUMNS) as DashboardBreakpoint[]) {
      const layout = nextLayouts[breakpoint];
      if (layout) normalized[breakpoint] = mergeLayoutCells(cellsByBreakpoint[breakpoint], layout);
    }
    onLayoutsChange(normalized);
  }, [editing, cellsByBreakpoint, onLayoutsChange]);

  return (
    <div ref={containerRef as unknown as Ref<HTMLDivElement>} className={`dashboard-rgl-shell ${editing ? "is-editing" : "is-viewing"}`}>
      {mounted && (
        <Responsive
          className="dashboard-rgl"
          width={width}
          layouts={layouts}
          breakpoints={BREAKPOINTS}
          cols={BREAKPOINT_COLUMNS}
          rowHeight={dashboard.rowHeight}
          margin={[10, 10]}
          containerPadding={[0, 0]}
          dragConfig={{
            enabled: editing,
            handle: ".dashboard-drag-handle",
            cancel: ".dashboard-cell-body, .dashboard-cell-actions, input, select, .dashboard-cell-remove, a"
          }}
          resizeConfig={{
            enabled: editing,
            handles: ["se"]
          }}
          compactor={fixedGridCompactor}
          autoSize
          onBreakpointChange={(breakpoint) => setActiveBreakpoint(toDashboardBreakpoint(breakpoint))}
          onLayoutChange={handleLayoutChange}
        >
          {activeCells.map((cell) => (
            <section key={cell.id} className={`dashboard-cell dashboard-cell-${cell.viewType}`}>
              <header className="pane-header pane-header-compact dashboard-cell-header">
                {editing ? <>
                  <button type="button" className="dashboard-drag-handle" aria-label="Move cell" title="Drag to move"><Icon name="drag" size={16} /></button>
                  <input
                    value={cell.title}
                    onChange={(event) => onUpdateCell(cell.id, (current) => ({ ...current, title: event.target.value }))}
                    aria-label="Cell title"
                  />
                  <select
                    value={cell.viewType}
                    onChange={(event) => onUpdateCell(cell.id, (current) => ({ ...current, viewType: event.target.value as DashboardCell["viewType"], title: titleForDashboardView(event.target.value as DashboardCell["viewType"]) }))}
                    aria-label="Cell view type"
                  >
                    {DASHBOARD_VIEW_TYPES.map((viewType) => <option key={viewType} value={viewType}>{titleForDashboardView(viewType)}</option>)}
                  </select>
                  {renderCellActions && <div className="dashboard-cell-actions dashboard-cell-edit-actions">{renderCellActions(cell, true)}</div>}
                  <button type="button" className="dashboard-cell-remove" onClick={() => onRemoveCell(cell.id)} disabled={activeCells.length <= 1} aria-label="Remove cell" title="Remove cell"><Icon name="delete" size={15} /></button>
                </> : <>
                  <Icon className="pane-header-icon" name={dashboardViewIcons[cell.viewType]} size={14} />
                  <strong className="pane-header-title">{cell.title}</strong>
                  {renderCellActions && <div className="dashboard-cell-actions">{renderCellActions(cell, false)}</div>}
                </>}
              </header>
              <div className="dashboard-cell-body">
                {renderCell(cell)}
              </div>
            </section>
          ))}
        </Responsive>
      )}
    </div>
  );
}
const BREAKPOINTS: Record<DashboardBreakpoint, number> = { desktop: 1200, tablet: 700, mobile: 0 };
const BREAKPOINT_COLUMNS: Record<DashboardBreakpoint, number> = { desktop: 24, tablet: 12, mobile: 4 };

function breakpointForWidth(width: number): DashboardBreakpoint {
  if (width >= BREAKPOINTS.desktop) return "desktop";
  if (width >= BREAKPOINTS.tablet) return "tablet";
  return "mobile";
}

function toDashboardBreakpoint(breakpoint: string): DashboardBreakpoint {
  return breakpoint === "desktop" || breakpoint === "tablet" || breakpoint === "mobile"
    ? breakpoint
    : "desktop";
}

function toLayoutItem(cell: DashboardCell): LayoutItem {
  return {
    i: cell.id,
    x: cell.grid.x,
    y: cell.grid.y,
    w: cell.grid.w,
    h: cell.grid.h,
    minW: 2,
    maxW: 48,
    minH: 3,
    maxH: 40,
    isBounded: true
  };
}

function buildResponsiveCells(cells: DashboardCell[], saved: DashboardResponsiveLayouts | undefined): Record<DashboardBreakpoint, DashboardCell[]> {
  return {
    desktop: saved?.desktop ?? cells,
    tablet: saved?.tablet ?? fallbackLayout(cells, 12, 2),
    mobile: saved?.mobile ?? fallbackLayout(cells, 4, 1)
  };
}

function fallbackLayout(cells: DashboardCell[], columns: number, columnCount: number) {
  const slotWidth = Math.floor(columns / columnCount);
  const result: DashboardCell[] = [];
  let y = 0;
  for (let index = 0; index < cells.length; index += columnCount) {
    const row = cells.slice(index, index + columnCount);
    const rowHeight = Math.max(...row.map((cell) => cell.grid.h), 3);
    row.forEach((cell, column) => {
      result.push({
        ...cell,
        grid: {
          x: column * slotWidth,
          y,
          w: slotWidth,
          h: cell.grid.h
        }
      });
    });
    y += rowHeight;
  }
  return result;
}

function mergeLayoutCells(cells: DashboardCell[], layout: Layout) {
  const positions = new Map(layout.map((item) => [item.i, item]));
  return cells.map((cell) => {
    const item = positions.get(cell.id);
    return item ? { ...cell, grid: { x: item.x, y: item.y, w: item.w, h: item.h } } : cell;
  });
}

const DASHBOARD_VIEW_TYPES: DashboardCell["viewType"][] = ["streams", "detail", "timeline", "topology", "events"];

function titleForDashboardView(viewType: DashboardCell["viewType"]) {
  switch (viewType) {
    case "streams": return "Streams";
    case "detail": return "Inspector";
    case "timeline": return "Timeline";
    case "topology": return "Topology";
    case "events": return "Events";
