    case "streams": return "Streams";
    case "detail": return "Inspector";
    case "timeline": return "Timeline";
    case "topology": return "Topology";
    case "events": return "Events";
  }
}

function nextDashboardY(cells: DashboardCell[]) {
  return cells.reduce((max, cell) => Math.max(max, cell.grid.y + cell.grid.h), 0);
}

function clampDashboardCell(cell: DashboardCell, columns: number): DashboardCell {
  const width = Math.max(2, Math.min(columns, Math.round(cell.grid.w)));
  const height = Math.max(3, Math.min(40, Math.round(cell.grid.h)));
  return {
    ...cell,
    title: cell.title || titleForDashboardView(cell.viewType),
    grid: {
      x: Math.max(0, Math.min(columns - width, Math.round(cell.grid.x))),
      y: Math.max(0, Math.min(200, Math.round(cell.grid.y))),
      w: width,
      h: height
    }
  };
}

function compareTimelineRows(a: TimelineRow, b: TimelineRow, streamOrder: Map<string, number>) {
  const positionA = streamOrder.get(a.streamKey);
  const positionB = streamOrder.get(b.streamKey);
  if (positionA !== undefined || positionB !== undefined) {
    if (positionA === undefined) return 1;
    if (positionB === undefined) return -1;
    return positionA - positionB;
  }
  return b.lastSeen - a.lastSeen || a.label.localeCompare(b.label) || a.streamKey.localeCompare(b.streamKey);
}

function timelineRowKey(row: TimelineRow) {
  if (row.rowType === "flow") {
    return `flow:${row.parentStreamKey ?? row.streamKey}::${row.flowKey ?? row.streamKey}`;
  }
  return `stream:${row.streamKey}`;
}

function formatTimeTravel(epochSec: number) {
  return new Date(epochSec * 1000).toLocaleString(undefined, { hour12: false });
}

function standaloneViewFromPath(pathname: string): StandaloneView {
  switch (pathname.replace(/\/+$/, "")) {
    case "/view/streams":
      return "streams";
    case "/view/timeline":
      return "timeline";
    case "/view/events":
      return "events";
    case "/view/detail":
      return "detail";
    default:
      return null;
  }
}

function dashboardCellTextParam(cell: DashboardCell, key: string) {
  const value = cell.params?.[key];
  return typeof value === "string" ? value : "";
}

function dashboardDetailTarget(cell: DashboardCell): { mode: "follow" } | { mode: "pinned"; streamKey: string; flowKey: string | null } {
  const mode = dashboardCellTextParam(cell, "detailTargetMode");
  if (mode === "follow") return { mode: "follow" };
  const streamKey = dashboardCellTextParam(cell, "targetStreamKey");
  if (!streamKey) return { mode: "follow" };
  const flowKey = dashboardCellTextParam(cell, "targetFlowKey");
  return { mode: "pinned", streamKey, flowKey: flowKey || null };
}

function dashboardTargetLabel(target: { streamKey: string; flowKey: string | null }, streams: StreamListItem[]) {
  const stream = streams.find((item) => item.streamKey === target.streamKey);
  const flow = target.flowKey ? stream?.flows.find((item) => item.flowKey === target.flowKey) : undefined;
  if (flow) return `${flow.endpointSrc ?? "Unknown endpoint"} ⟶ ${flow.endpointDst ?? "Unknown endpoint"}`;
  return stream ? streamEndpointLabel(stream) : target.streamKey;
}

function DashboardTargetDrawer({
  open,
  streams,
  interfaces,
  selectedStreamKey,
  selectedFlowKey,
  onClose,
  onSelectStream,
  onSelectFlow
}: {
  open: boolean;
  streams: StreamListItem[];
  interfaces: InterfaceListItem[];
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  onClose: () => void;
  onSelectStream: (streamKey: string) => void;
  onSelectFlow: (streamKey: string, flowKey: string) => void;
}) {
  const [query, setQuery] = useState("");
  const visibleStreams = useMemo(() => filterDashboardPickerStreams(streams, query), [streams, query]);
  const visibleInterfaceIds = useMemo(() => new Set(visibleStreams.map((stream) => stream.interfaceId).filter((id): id is number => id !== undefined)), [visibleStreams]);
  const visibleInterfaces = useMemo(() => interfaces.filter((item) => item.interfaceId === undefined || visibleInterfaceIds.has(item.interfaceId)), [interfaces, visibleInterfaceIds]);

  useEffect(() => {
    if (!open) return;
    setQuery("");
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [open, onClose]);

  if (!open) return null;
  return <div className="dashboard-target-drawer-backdrop" role="presentation" onPointerDown={(event) => { if (event.target === event.currentTarget) onClose(); }}>
    <aside className="dashboard-target-drawer" role="dialog" aria-modal="true" aria-label="Select Inspector target">
      <header className="dashboard-target-drawer-header">
        <div><strong>Select Inspector target</strong><small>Select a stream or a flow.</small></div>
        <button type="button" className="icon-button" onClick={onClose} aria-label="Close target selector" title="Close"><Icon name="close" size={17} /></button>
      </header>
      <div className="dashboard-target-drawer-search"><SearchInput value={query} onChange={setQuery} placeholder="Search streams or flows" label="search streams and flows" /></div>
      <div className="dashboard-target-drawer-list">
        {visibleStreams.length === 0 ? <div className="dashboard-target-drawer-empty">No matching streams or flows.</div> : <StreamTable
          streams={visibleStreams}
          interfaces={visibleInterfaces}
          selectedStreamKey={selectedStreamKey}
          selectedFlowKey={selectedFlowKey}
          selectedInterfaceKey={null}
          overviewMode={false}
          expandLevel="flow"
          pickerMode
          onSelectInterface={() => undefined}
          onSelectStream={onSelectStream}
          onSelectFlow={onSelectFlow}
        />}
      </div>
    </aside>
  </div>;
}

function filterDashboardPickerStreams(streams: StreamListItem[], query: string) {
  if (!query.trim()) return streams;
  return streams.flatMap((stream) => {
    const streamMatches = matchesSearch([stream.kind, stream.proto, stream.label, stream.streamKey, stream.endpointA, stream.endpointB, stream.interfaceName, stream.flowRoles.join(" ")], query);
    if (streamMatches) return [stream];
    const flows = stream.flows.filter((flow) => matchesSearch([flow.flowKey, flow.label, flow.role, flow.endpointSrc, flow.endpointDst, flow.interfaceName], query));
    return flows.length > 0 ? [{ ...stream, flows, flowCount: flows.length }] : [];
  });
}

function DashboardDetailEmptyState({ onChoose }: { onChoose: () => void }) {
  return <aside className="detail-pane empty-state dashboard-detail-empty-state">
    <div>
      <p>Select a stream or flow to show Inspector.</p>
      <button type="button" className="button-with-icon" onClick={onChoose}><Icon name="targetFollow" size={15} />Select target</button>
    </div>
  </aside>;
}

function streamListItemToState(stream: StreamListItem): StreamState {
  return {
    ...stream,
    flows: stream.flows.map((flow) => ({ ...flow, metrics: {} }))
  };
}

function streamEndpointLabel(stream: StreamListItem) {
  const endpointA = stream.endpointA ?? "Unknown endpoint";
  return stream.endpointB ? `${endpointA} ⟶ ${stream.endpointB}` : endpointA;
}

function dashboardDetailMode(cell: DashboardCell): DetailMode {
  return dashboardCellTextParam(cell, "detailMode") === "detail" ? "detail" : "overview";
}

function dashboardEventsTab(cell: DashboardCell): EventLogTab {
  return dashboardCellTextParam(cell, "eventsTab") === "selected" ? "selected" : "all";
}

function filterStreams(streams: StreamListItem[], query: string) {
  if (!query.trim()) return streams;
  return streams.filter((stream) =>
    matchesSearch([stream.kind, stream.label, stream.streamKey, stream.interfaceName, stream.flowRoles.join(" "), ...stream.flows.map((flow) => flow.interfaceName)], query)
  );
}

function expandLevelFromParam(value: string | null): ExpandLevel {
  return value === "interface" || value === "proto" || value === "flow" || value === "stream" ? value : "stream";
}

function detailModeFromParam(value: string | null): DetailMode {
  return value === "detail" ? "detail" : "overview";
}

