export type TopologySnapshot = {
  time: number;
  nodes: TopologyNode[];
  edges: TopologyEdge[];
  [key: string]: unknown;
};

export type StreamsSnapshotResponse = {
  time: number;
  streams: StreamListItem[];
  interfaces: InterfaceListItem[];
};

