function dashboardDetailTarget(cell: DashboardCell): { mode: "follow" } | { mode: "pinned"; streamKey: string; flowKey: string | null } {
  const mode = dashboardCellTextParam(cell, "detailTargetMode");
  if (mode === "follow") return { mode: "follow" };
  const streamKey = dashboardCellTextParam(cell, "targetStreamKey");
  if (!streamKey) return { mode: "follow" };
  const flowKey = dashboardCellTextParam(cell, "targetFlowKey");
  return { mode: "pinned", streamKey, flowKey: flowKey || null };
}

function dashboardTargetLabel(target: { streamKey: string; flowKey: string | null }, streams: StreamListItem[]) {
  const stream = streams.find((item) => item.streamKey === target.streamKey);
  const flow = target.flowKey ? stream?.flows.find((item) => item.flowKey === target.flowKey) : undefined;
  if (flow) return `${flow.endpointSrc ?? "Unknown endpoint"} ⟶ ${flow.endpointDst ?? "Unknown endpoint"}`;
  return stream ? streamEndpointLabel(stream) : target.streamKey;
}

function DashboardTargetDrawer({
  open,
  streams,
  interfaces,
  selectedStreamKey,
  selectedFlowKey,
  onClose,
  onSelectStream,
  onSelectFlow
}: {
  open: boolean;
  streams: StreamListItem[];
  interfaces: InterfaceListItem[];
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  onClose: () => void;
  onSelectStream: (streamKey: string) => void;
  onSelectFlow: (streamKey: string, flowKey: string) => void;
}) {
  const [query, setQuery] = useState("");
  const visibleStreams = useMemo(() => filterDashboardPickerStreams(streams, query), [streams, query]);
  const visibleInterfaceIds = useMemo(() => new Set(visibleStreams.map((stream) => stream.interfaceId).filter((id): id is number => id !== undefined)), [visibleStreams]);
  const visibleInterfaces = useMemo(() => interfaces.filter((item) => item.interfaceId === undefined || visibleInterfaceIds.has(item.interfaceId)), [interfaces, visibleInterfaceIds]);

  useEffect(() => {
    if (!open) return;
    setQuery("");
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [open, onClose]);

  if (!open) return null;
  return <div className="dashboard-target-drawer-backdrop" role="presentation" onPointerDown={(event) => { if (event.target === event.currentTarget) onClose(); }}>
    <aside className="dashboard-target-drawer" role="dialog" aria-modal="true" aria-label="Select Inspector target">
      <header className="dashboard-target-drawer-header">
        <div><strong>Select Inspector target</strong><small>Select a stream or a flow.</small></div>
        <button type="button" className="icon-button" onClick={onClose} aria-label="Close target selector" title="Close"><Icon name="close" size={17} /></button>
      </header>
      <div className="dashboard-target-drawer-search"><SearchInput value={query} onChange={setQuery} placeholder="Search streams or flows" label="search streams and flows" /></div>
      <div className="dashboard-target-drawer-list">
        {visibleStreams.length === 0 ? <div className="dashboard-target-drawer-empty">No matching streams or flows.</div> : <StreamTable
          streams={visibleStreams}
          interfaces={visibleInterfaces}
          selectedStreamKey={selectedStreamKey}
          selectedFlowKey={selectedFlowKey}
          selectedInterfaceKey={null}
          overviewMode={false}
          expandLevel="flow"
          pickerMode
          onSelectInterface={() => undefined}
          onSelectStream={onSelectStream}
          onSelectFlow={onSelectFlow}
        />}
      </div>
    </aside>
  </div>;
}

function filterDashboardPickerStreams(streams: StreamListItem[], query: string) {
  if (!query.trim()) return streams;
  return streams.flatMap((stream) => {
    const streamMatches = matchesSearch([stream.kind, stream.proto, stream.label, stream.streamKey, stream.endpointA, stream.endpointB, stream.interfaceName, stream.flowRoles.join(" ")], query);
    if (streamMatches) return [stream];
    const flows = stream.flows.filter((flow) => matchesSearch([flow.flowKey, flow.label, flow.role, flow.endpointSrc, flow.endpointDst, flow.interfaceName], query));
    return flows.length > 0 ? [{ ...stream, flows, flowCount: flows.length }] : [];
  });
}

