  border-radius: 0;
  background: transparent;
  color: var(--text);
  font-size: var(--font-size-xs);
}

.event-column-resizers {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
}

.event-column-resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 10px;
  transform: translateX(-50%);
  cursor: col-resize;
  pointer-events: auto;
  touch-action: none;
}

.event-column-resizer::before {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 4px;
  width: 1px;
  background: transparent;
  content: "";
}

.event-column-resizer:hover::before,
.event-column-resizer:active::before {
  background: var(--accent);
}

.event-time, .event-level, .event-target, .event-message {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.event-row:hover {
  background: var(--surface-muted);
}

.event-row.time-selected {
  background: var(--accent-soft);
  box-shadow: inset 3px 0 0 var(--accent);
}

.event-time {
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.event-level {
  width: fit-content;
  padding: 2px 4px;
  border-radius: var(--radius-sm);
  background: var(--success-soft);
  color: var(--success);
  font-size: 10px;
  line-height: 1;
}

.event-row.warn .event-level {
  background: var(--warning-soft);
  color: var(--warning);
}

.event-row.error .event-level {
  background: var(--danger-soft);
  color: var(--danger);
}

.event-context {
  min-height: 0;
  padding: var(--space-2) var(--space-3);
  border-top: 1px solid var(--line);
  background: var(--surface-muted);
  overflow: auto;
}

.event-context-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  margin-bottom: var(--space-2);
}

.event-context-header strong {
  color: var(--text-strong);
  font-size: var(--font-size-sm);
}

.event-context-header button {
  min-height: 22px;
  width: 22px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 18px;
}

.event-context dl {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  gap: 4px var(--space-2);
  margin: 0;
  font-size: var(--font-size-xs);
