    selectedInterfaceKeyRef.current = selectedInterfaceKey;
  }, [selectedInterfaceKey, selectedMetricsRange, selectedTimeSec]);

  useEffect(() => {
    void getBootstrap()
      .then((bootstrap) => {
        setStreams(bootstrap.streams);
        setInterfaces(bootstrap.interfaces);
        setSummary(bootstrap.summary);
        updateLiveSummary(bootstrap.summary);
        if (!eventsLoadedRef.current) setEvents(bootstrap.events);
        setBootstrapped(true);
        if (!selectedStreamKey && bootstrap.streams.length > 0) onDefaultSelect?.(bootstrap.streams[0].streamKey);
        latestServerOrderRef.current = bootstrap.streams.map((item) => item.streamKey);
      })
      .catch(() => undefined);
  }, []);

  useEffect(() => {
  const activeTimelineFollowNow = dashboardTimeContextActive
    ? !dashboardPaused && dashboardContextTimeSec === null
    : !paused && tabContextTimeSec === null && timelineFollowNow;
  const activeManualTimelineWindowEndSec = dashboardTimeContextActive
    ? dashboardContextTimeSec
    : tabContextTimeSec ?? manualTimelineWindowEndSec;

  const {
    streams,
    interfaces,
    timeline,
    timelineGaps,
    timelineWindow,
    timelineAvailable,
    timelineSource,
    timelineLoading,
    summary,
    liveSummary,
    liveUpdateReceivedAt,
    selectedListItem,
    selectedStream,
    selectedMetrics,
    selectedInterface,
    selectedInterfaceMetrics,
    socketState,
    events,
    bootstrapped
  } = useStreams(
    selectedStreamKey,
    selectedInterfaceKey,
    activePaused,
    activeMetricsRange,
    activeTimelineRange,
    activeEventsRange,
    activeTimelineFollowNow,
    activeManualTimelineWindowEndSec,
    streamSortRefreshToken,
    activeSelectedTimeSec,
    setSelectedStreamKey,
    (nextConfig) => {
      setAppConfig(nextConfig);
      setMaintenanceRefreshToken((current) => current + 1);
    }
  );
  useEffect(() => {

    const syncLatestAvailable = () => {
      const latest = liveSummary.updatedAt;
      if (!latest) {
        setLatestAvailableTimeSec(null);
        return;
      }
      const now = Date.now() / 1000;
      const isFresh = now - latest <= appConfig.staleAfterSec
        || (liveUpdateReceivedAt !== null && now - liveUpdateReceivedAt <= appConfig.staleAfterSec);
      setLatestAvailableTimeSec(isFresh ? null : latest);
        : isLatestAvailable
          ? "Latest available"
          : summary.updatedAt
            ? "Live"
            : "Waiting";
  const liveTone = isLatestAvailable || contextTimeSec !== null || contextPaused || !summary.updatedAt ? "warning" as const : "success" as const;
  const toggleTheme = () => setTheme((current) => (current === "light" ? "dark" : "light"));
  const toggleLive = () => dashboardTimeContextActive
    ? dashboardLocalTimeSec !== null || dashboardPaused || isLatestAvailable ? resumeDashboardLive() : pauseDashboardLive()
    : selectedTimeSec !== null || paused || isLatestAvailable ? resumeLiveTime() : setPaused((current) => !current);

  const renderStatusHeader = (title: string, icon: IconName) => (
    <AppContextBar
      compact
      title={title}
      icon={icon}
      updatedLabel={contextUpdatedLabel}
      socketState={socketState}
      liveLabel={liveLabel}
      liveTone={liveTone}
      onToggleLive={toggleLive}
      onToggleTheme={toggleTheme}
      theme={theme}
    />
  );

  const renderStandaloneSearch = (placeholder: string) => (
    <SearchInput className="standalone-search" value={query} onChange={setQuery} placeholder={placeholder} label="search" />
  );

  const selectGlobalTime = (timeSec: number) => {
    setSelectedTimeSec(timeSec);
    setPaused(true);
    setTimelineFollowNow(false);
    setManualTimelineWindowEndSec(timeSec);
  };

  const resumeLiveTime = () => {
    setSelectedTimeSec(null);
    setPaused(false);
    setTimelineFollowNow(true);
  flowKey?: string;
  interfaceId?: number;
  limit?: number;
  from?: number;
  to?: number;
  proto?: string;
  level?: "info" | "warn" | "error";
  type?: string;
} = {}): Promise<EventLogItem[]> {
  const query = new URLSearchParams();
  if (params.streamKey) query.set("streamKey", params.streamKey);
  if (params.flowKey) query.set("flowKey", params.flowKey);
  if (params.interfaceId !== undefined) query.set("interfaceId", String(params.interfaceId));
  if (params.from !== undefined) query.set("from", String(params.from));
  if (params.to !== undefined) query.set("to", String(params.to));
  if (params.proto) query.set("proto", params.proto);
  if (params.level) query.set("level", params.level);
  if (params.type) query.set("type", params.type);
  if (params.limit) query.set("limit", String(params.limit));
  const suffix = query.toString() ? `?${query.toString()}` : "";
  return getJson(`/api/events${suffix}`);
}

async function getJson<T>(url: string): Promise<T> {
  const response = await fetch(url, { cache: "no-store" });
  if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
  return response.json() as Promise<T>;
}

