            metrics: {}
          }))
  const selectGlobalTime = (timeSec: number) => {
    setSelectedTimeSec(timeSec);
    setPaused(true);
    setTimelineFollowNow(false);
    setManualTimelineWindowEndSec(timeSec);
  };

  const resumeLiveTime = () => {
    setSelectedTimeSec(null);
    setPaused(false);
    setTimelineFollowNow(true);
    setManualTimelineWindowEndSec(null);
  };

  const selectDashboardTime = (timeSec: number) => {
    setDashboardSelectedTimeSec(timeSec);
    setDashboardPaused(false);
    setDashboardPauseTimeSec(null);
  };
  const pauseDashboardLive = () => {
    setDashboardSelectedTimeSec(null);
    setDashboardPaused(true);
    setDashboardPauseTimeSec(summary.updatedAt ?? Date.now() / 1000);
  };
  const resumeDashboardLive = () => {
    setDashboardSelectedTimeSec(null);
    setDashboardPaused(false);
    setDashboardPauseTimeSec(null);
  };

  const selectDashboardStream = (streamKey: string) => setDashboardSelection({ streamKey, flowKey: null });
  const selectDashboardFlow = (streamKey: string, flowKey: string) => setDashboardSelection({ streamKey, flowKey });
  const dashboardSelectedStreamKey = dashboardSelection?.streamKey ?? null;
  const dashboardSelectedFlowKey = dashboardSelection?.flowKey ?? null;
  const openDashboardTargetPicker = (cellId: string, mode: "follow" | "pinned") => setDashboardTargetPicker({ cellId, mode });

  const dashboardLayout = dashboardLayouts.find((layout) => layout.id === dashboardLayoutId) ?? dashboardLayouts[0] ?? DEFAULT_DASHBOARD_LAYOUT;
  const dashboardContextLabel = dashboardSelectedTimeSec !== null ? formatTimeTravel(dashboardSelectedTimeSec) : dashboardPaused ? "Paused" : latestAvailableTimeSec !== null ? "Latest available" : summary.updatedAt ? "Live" : "Waiting";

  const updateDashboardCell = (cellId: string, updater: (cell: DashboardCell) => DashboardCell) => {
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => layouts.map((layout) => layout.id !== dashboardLayout.id ? layout : {
      ...layout,
      cells: layout.cells.map((cell) => cell.id === cellId ? clampDashboardCell(updater(cell), layout.columns) : cell),
      layouts: layout.layouts ? Object.fromEntries(
