output.text:
type EventLogProps = {
  events: EventLogItem[];
  eventsRange: string;
  onChangeEventsRange: (value: string) => void;
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  selectedInterfaceId: number | null;
  initialQuery?: string;
  query?: string;
  onChangeQuery?: (value: string) => void;
  showSearch?: boolean;
  tab?: EventLogTab;
  onChangeTab?: (tab: EventLogTab) => void;
  showHeader?: boolean;
  selectedTimeSec?: number | null;
  onSelectTime?: (timeSec: number) => void;
  syncTimeOnRowClick?: boolean;
  onSyncTime?: (timeSec: number) => void;
  columnWidths?: EventColumnWidths;
  onChangeColumnWidths?: (widths: EventColumnWidths) => void;
};

export type EventLogTab = "all" | "selected";

export function EventLog({
  events,
  eventsRange,
  onChangeEventsRange,
  selectedStreamKey,
  selectedFlowKey,
  selectedInterfaceId,
  initialQuery = "",
  query: controlledQuery,
  onChangeQuery,
  showSearch = true,
  tab: controlledTab,
  onChangeTab,
  showHeader = true,
  selectedTimeSec = null,
  onSelectTime,
  syncTimeOnRowClick = true,
  onSyncTime,
  columnWidths: controlledColumnWidths,
  onChangeColumnWidths
}: EventLogProps) {
  const [internalTab, setInternalTab] = useState<EventLogTab>("all");
  const [internalQuery, setInternalQuery] = useState(initialQuery);
  const [internalColumnWidths, setInternalColumnWidths] = useState<EventColumnWidths>(loadStoredColumnWidths);
  const [selectedEvent, setSelectedEvent] = useState<EventLogItem | null>(null);
  const [localSelectionSnapshot, setLocalSelectionSnapshot] = useState<LocalSelectionSnapshot | null>(null);
  const [listWidth, setListWidth] = useState(0);
  const listRef = useRef<HTMLDivElement | null>(null);
  const listFrameRef = useRef<HTMLDivElement | null>(null);
  const scrollSnapshotRef = useRef({ top: 0, height: 0 });
  const followLatestRef = useRef(true);
  const eventRowRefs = useRef(new Map<string, HTMLButtonElement>());
  const lastAutoScrolledKeyRef = useRef<string | null>(null);
  const locallySelectedEventIdRef = useRef<string | null>(null);
  const localSelectionScrollAnchorRef = useRef<LocalSelectionScrollAnchor | null>(null);
  const tab = controlledTab ?? internalTab;
    event.preventDefault();
    event.stopPropagation();
    const list = listRef.current;
    if (!list) return;
    const row = list.querySelector<HTMLElement>(".event-row");
    const context = document.createElement("canvas").getContext("2d");
    if (!context) return;
    context.font = getComputedStyle(row ?? list).font;
    const widest = renderedEvents.slice(0, AUTO_FIT_SAMPLE_SIZE).reduce((max, item) => Math.max(max, context.measureText(eventColumnText(item, column)).width), 0);
    const limits = EVENT_COLUMN_LIMITS[column];
    applyColumnWidths({ ...columnWidths, [column]: clamp(Math.ceil(widest) + 12, limits.min, limits.max) });
  };

  const captureLocalSelectionAnchor = (event: EventLogItem) => {
    const list = listRef.current;
    const row = eventRowRefs.current.get(event.id);
    if (!list || !row) return;
    localSelectionScrollAnchorRef.current = {
      eventId: event.id,
      scrollTop: list.scrollTop,
      rowOffset: row.getBoundingClientRect().top - list.getBoundingClientRect().top
    };
  };

  const syncEventTime = (event: EventLogItem, callback: ((timeSec: number) => void) | undefined) => {
    if (!callback) return;
    captureLocalSelectionAnchor(event);
    locallySelectedEventIdRef.current = event.id;
    setLocalSelectionSnapshot({ events: visibleEvents, tab, query: normalizedQuery, eventsRange });
    callback(event.time);
  };

  const selectEvent = (event: EventLogItem) => {
    captureLocalSelectionAnchor(event);
    setSelectedEvent(event);
    if (syncTimeOnRowClick) syncEventTime(event, onSelectTime);
  };

  return (
    <section className={`events-card ${showHeader ? "" : "events-card-embedded"}`}>
      {showHeader && (
        <div className="pane-header events-header">
          <div className="pane-header-title-with-icon"><Icon className="pane-header-icon" name="events" size={14} /><h3>Events</h3></div>
          <div className="events-actions">
            {showSearch && <SearchInput className="event-search" value={query} onChange={setQuery} placeholder="Search events" label="event search" />}
            <label className="detail-range-select" title="Event range">
              <span>Range</span>
              <select value={eventsRange} onChange={(event) => onChangeEventsRange(event.target.value)}>
                <option value="24h">24h</option>
                <option value="12h">12h</option>
                <option value="6h">6h</option>
                <option value="3h">3h</option>
                <option value="1h">1h</option>
                <option value="30m">30m</option>
                <option value="10m">10m</option>
                <option value="5m">5m</option>
              </select>
            </label>
            <div className="events-tabs">
              <button className={tab === "all" ? "active" : ""} onClick={() => setTab("all")}>All</button>
              <button className={tab === "selected" ? "active" : ""} onClick={() => setTab("selected")}>Selected</button>
            </div>
          </div>
        </div>
      )}
      <div className={`events-content ${selectedEvent ? "has-context" : ""}`}>
        <div ref={listFrameRef} className="events-list-frame" style={columnStyle}>
          <div
            ref={listRef}
            className="events-list"
            onScroll={(event) => {
              const element = event.currentTarget;
              followLatestRef.current = element.scrollTop <= 8;
              scrollSnapshotRef.current = { top: element.scrollTop, height: element.scrollHeight };
            }}
          >
            {renderedEvents.length === 0 ? (
              <div className="events-empty">No events</div>
            ) : (
              <>
                {visibleEvents.length > MAX_RENDERED_EVENTS && <div className="events-empty">Showing latest {MAX_RENDERED_EVENTS} / {visibleEvents.length} events</div>}
                {renderedEvents.map((event) => (
                  <EventRow
                    key={event.id}
                    event={event}
                    selected={selectedEvent?.id === event.id || (selectedTimeSec !== null && Math.abs(event.time - selectedTimeSec) < 0.5)}
                    syncTimeOnSelect={syncTimeOnRowClick && onSelectTime !== undefined}
                    onSelect={() => selectEvent(event)}
                    eventRef={(element) => {
                      if (element) eventRowRefs.current.set(event.id, element);
                      else eventRowRefs.current.delete(event.id);
                    }}
                  />
                ))}
              </>
            )}
          </div>
          <EventColumnResizers widths={effectiveColumnWidths} onResizeStart={resizeColumn} onAutoFit={autoFitColumn} />
        {selectedEvent && <EventContext
          event={selectedEvent}
          onSyncTime={onSyncTime ? () => syncEventTime(selectedEvent, onSyncTime) : undefined}
          onClose={() => {
            locallySelectedEventIdRef.current = null;
            lastAutoScrolledKeyRef.current = null;
            setLocalSelectionSnapshot(null);
            setSelectedEvent(null);
          }}
        />}
        }} />}
      </div>
    </section>
  );
}

function EventColumnResizers({
  widths,
  onResizeStart,
  onAutoFit
}: {
  widths: EventColumnWidths;
  onResizeStart: (column: EventColumn, event: ReactPointerEvent<HTMLDivElement>) => void;
  onAutoFit: (column: EventColumn, event: ReactMouseEvent<HTMLDivElement>) => void;
}) {
  const left = EVENT_ROW_SIDE_PADDING_PX + widths.time + EVENT_COLUMN_GAP_PX / 2;
  const boundaries: Array<{ column: EventColumn; left: number; label: string }> = [
    { column: "time", left, label: "Resize time column" },
    { column: "level", left: left + EVENT_COLUMN_GAP_PX / 2 + widths.level + EVENT_COLUMN_GAP_PX / 2, label: "Resize level column" },
    { column: "target", left: left + EVENT_COLUMN_GAP_PX / 2 + widths.level + EVENT_COLUMN_GAP_PX + widths.target + EVENT_COLUMN_GAP_PX / 2, label: "Resize target column" }
  ];
  return <div className="event-column-resizers">{boundaries.map(({ column, left: offset, label }) => (
    <div
      key={column}
      className="event-column-resizer"
      style={{ left: offset }}
      role="separator"
      aria-orientation="vertical"
