  const timeLabel = formatEventTime(event.time);
  const targetLabel = event.targetLabel ?? event.proto ?? event.scope;
  return (
    <button ref={eventRef} type="button" className={`event-row ${event.level} ${selected ? "time-selected" : ""}`} onClick={onSelect} title={syncTimeOnSelect ? "Inspect this event and sync its timestamp" : "Inspect this event"}>
