import { useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type MouseEvent as ReactMouseEvent, type PointerEvent as ReactPointerEvent } from "react";
import type { EventLogItem } from "../types/api";
import { SearchInput } from "./ui/SearchInput";
import { Icon } from "./ui/Icon";
import { matchesSearch } from "./search";

const MAX_RENDERED_EVENTS = 8000;
const AUTO_FIT_SAMPLE_SIZE = 240;
const EVENT_LIST_STORAGE_KEY = "stm-events-column-widths";
const EVENT_ROW_SIDE_PADDING_PX = 8;
const EVENT_COLUMN_GAP_PX = 4;
const MIN_MESSAGE_COLUMN_PX = 120;
export const DEFAULT_EVENT_COLUMN_WIDTHS = { time: 180, level: 42, target: 260 };
const EVENT_COLUMN_LIMITS = {
  time: { min: 125, max: 260 },
  level: { min: 38, max: 76 },
  target: { min: 180, max: 600 }
} as const;

type EventColumn = keyof EventColumnWidths;

export type EventColumnWidths = {
  time: number;
  level: number;
  target: number;
};

type LocalSelectionScrollAnchor = {
  eventId: string;
  scrollTop: number;
  rowOffset: number;
};

type LocalSelectionSnapshot = {
  events: EventLogItem[];
  tab: EventLogTab;
  query: string;
  eventsRange: string;
};

type EventLogProps = {
  events: EventLogItem[];
  eventsRange: string;
  onChangeEventsRange: (value: string) => void;
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  selectedInterfaceId: number | null;
  initialQuery?: string;
  query?: string;
  onChangeQuery?: (value: string) => void;
  showSearch?: boolean;
  tab?: EventLogTab;
  onChangeTab?: (tab: EventLogTab) => void;
  showHeader?: boolean;
  selectedTimeSec?: number | null;
  onSelectTime?: (timeSec: number) => void;
  syncTimeOnRowClick?: boolean;
  onSyncTime?: (timeSec: number) => void;
  columnWidths?: EventColumnWidths;
  onChangeColumnWidths?: (widths: EventColumnWidths) => void;
};

export type EventLogTab = "all" | "selected";

export function EventLog({
  events,
  eventsRange,
  onChangeEventsRange,
  selectedStreamKey,
  selectedFlowKey,
  selectedInterfaceId,
  initialQuery = "",
  query: controlledQuery,
  onChangeQuery,
  showSearch = true,
  tab: controlledTab,
  onChangeTab,
  showHeader = true,
  selectedTimeSec = null,
  onSelectTime,
  syncTimeOnRowClick = true,
  onSyncTime,
  columnWidths: controlledColumnWidths,
  onChangeColumnWidths
}: EventLogProps) {
  const [internalTab, setInternalTab] = useState<EventLogTab>("all");
  const [internalQuery, setInternalQuery] = useState(initialQuery);
  const [internalColumnWidths, setInternalColumnWidths] = useState<EventColumnWidths>(loadStoredColumnWidths);
  const [selectedEvent, setSelectedEvent] = useState<EventLogItem | null>(null);
  const [localSelectionSnapshot, setLocalSelectionSnapshot] = useState<LocalSelectionSnapshot | null>(null);
  const [listWidth, setListWidth] = useState(0);
  const listRef = useRef<HTMLDivElement | null>(null);
  const listFrameRef = useRef<HTMLDivElement | null>(null);
  const scrollSnapshotRef = useRef({ top: 0, height: 0 });
  const followLatestRef = useRef(true);
  const eventRowRefs = useRef(new Map<string, HTMLButtonElement>());
  const lastAutoScrolledKeyRef = useRef<string | null>(null);
  const locallySelectedEventIdRef = useRef<string | null>(null);
  const localSelectionScrollAnchorRef = useRef<LocalSelectionScrollAnchor | null>(null);
  const tab = controlledTab ?? internalTab;
  const setTab = onChangeTab ?? setInternalTab;
  const query = controlledQuery ?? internalQuery;
  const setQuery = onChangeQuery ?? setInternalQuery;
  const columnWidths = normalizeColumnWidths(controlledColumnWidths ?? internalColumnWidths);
  const scopedEvents = tab === "all" ? events : events.filter((event) => {
    if (selectedFlowKey) return event.flowKey === selectedFlowKey || event.streamKey === selectedStreamKey;
    if (selectedStreamKey) return event.streamKey === selectedStreamKey;
    if (selectedInterfaceId !== null) return event.interfaceId === selectedInterfaceId;
    return false;
  });
  const normalizedQuery = query.trim();
  const matchingEvents = normalizedQuery ? scopedEvents.filter((event) => eventMatches(event, query)) : scopedEvents;
  const visibleEvents = localSelectionSnapshot?.events ?? matchingEvents;
  const renderedEvents = visibleEvents.slice(0, MAX_RENDERED_EVENTS);
  const timeSelectedEvent = useMemo(() => closestEventWithin(renderedEvents, selectedTimeSec), [renderedEvents, selectedTimeSec]);
  const primarySelectedEventId = selectedEvent && renderedEvents.some((event) => event.id === selectedEvent.id)
    ? selectedEvent.id
    : timeSelectedEvent?.id ?? null;
  const visibleSignature = `${visibleEvents[0]?.id ?? ""}:${visibleEvents.length}:${visibleEvents[visibleEvents.length - 1]?.id ?? ""}`;
  const effectiveColumnWidths = useMemo(() => fitColumnWidths(columnWidths, listWidth), [columnWidths, listWidth]);
  const columnStyle = useMemo(() => ({
    "--event-time-width": `${effectiveColumnWidths.time}px`,
    "--event-level-width": `${effectiveColumnWidths.level}px`,
    "--event-target-width": `${effectiveColumnWidths.target}px`
  }) as CSSProperties, [effectiveColumnWidths]);

  useLayoutEffect(() => {
    const element = listFrameRef.current;
    if (!element) return;
    const update = () => setListWidth(element.clientWidth);
    update();
    const observer = new ResizeObserver(update);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  useLayoutEffect(() => {
    const snapshot = localSelectionSnapshot;
    if (!snapshot) return;
    const selectionIsCurrent = selectedEvent !== null
      && selectedTimeSec === selectedEvent.time
      && snapshot.tab === tab
      && snapshot.query === normalizedQuery
      && snapshot.eventsRange === eventsRange;
    if (selectionIsCurrent) return;
    setLocalSelectionSnapshot(null);
  }, [eventsRange, localSelectionSnapshot, normalizedQuery, selectedEvent, selectedTimeSec, tab]);

  useLayoutEffect(() => {
    const element = listRef.current;
    if (!element || visibleEvents.length === 0) return;
    const prev = scrollSnapshotRef.current;
    const heightDelta = element.scrollHeight - prev.height;
    if (!followLatestRef.current && heightDelta !== 0) element.scrollTop = prev.top + heightDelta;
    scrollSnapshotRef.current = { top: element.scrollTop, height: element.scrollHeight };
  }, [visibleSignature, tab, normalizedQuery, eventsRange, visibleEvents.length]);

  useLayoutEffect(() => {
    const anchor = localSelectionScrollAnchorRef.current;
    if (!anchor || selectedEvent?.id !== anchor.eventId) return;
    const list = listRef.current;
    const row = eventRowRefs.current.get(anchor.eventId);
    if (!list || !row) return;

    const rowOffset = row.getBoundingClientRect().top - list.getBoundingClientRect().top;
    list.scrollTop = Math.max(0, anchor.scrollTop + rowOffset - anchor.rowOffset);
    scrollSnapshotRef.current = { top: list.scrollTop, height: list.scrollHeight };
    localSelectionScrollAnchorRef.current = null;
  }, [selectedEvent?.id]);

  useLayoutEffect(() => {
    if (selectedTimeSec === null) {
      lastAutoScrolledKeyRef.current = null;
      locallySelectedEventIdRef.current = null;
      return;
    }

    const selected = timeSelectedEvent;
    if (!selected) return;
    const scrollKey = selected.id + ":" + visibleSignature;
    if (lastAutoScrolledKeyRef.current === scrollKey) return;

    if (locallySelectedEventIdRef.current === selected.id) {
      lastAutoScrolledKeyRef.current = scrollKey;
      return;
    }
    locallySelectedEventIdRef.current = null;

    const frame = window.requestAnimationFrame(() => {
      const row = eventRowRefs.current.get(selected.id);
      const list = listRef.current;
      if (!row || !list) return;

      const rowBounds = row.getBoundingClientRect();
      const listBounds = list.getBoundingClientRect();
      const inset = 4;
      let offset = 0;
      if (rowBounds.top < listBounds.top + inset) offset = rowBounds.top - listBounds.top - inset;
      else if (rowBounds.bottom > listBounds.bottom - inset) offset = rowBounds.bottom - listBounds.bottom + inset;
      if (offset === 0) {
        lastAutoScrolledKeyRef.current = scrollKey;
        return;
      }

      followLatestRef.current = false;
      list.scrollTop = Math.max(0, list.scrollTop + offset);
      scrollSnapshotRef.current = { top: list.scrollTop, height: list.scrollHeight };
      lastAutoScrolledKeyRef.current = scrollKey;
    });
    return () => window.cancelAnimationFrame(frame);
  }, [selectedTimeSec, visibleSignature, renderedEvents.length]);

  const applyColumnWidths = (next: EventColumnWidths) => {
    const normalized = normalizeColumnWidths(next);
    if (onChangeColumnWidths) {
      onChangeColumnWidths(normalized);
      return;
    }
    setInternalColumnWidths(normalized);
    try { window.localStorage.setItem(EVENT_LIST_STORAGE_KEY, JSON.stringify(normalized)); } catch { /* Storage may be unavailable. */ }
  };

  const resizeColumn = (column: EventColumn, event: ReactPointerEvent<HTMLDivElement>) => {
    if (window.matchMedia("(max-width: 720px)").matches) return;
    event.preventDefault();
    event.stopPropagation();
    const startX = event.clientX;
    const startWidth = columnWidths[column];
    const previousCursor = document.body.style.cursor;
    document.body.style.cursor = "col-resize";

    const onMove = (moveEvent: PointerEvent) => {
      const limits = EVENT_COLUMN_LIMITS[column];
      applyColumnWidths({ ...columnWidths, [column]: clamp(startWidth + moveEvent.clientX - startX, limits.min, limits.max) });
    };
    const onUp = () => {
      document.body.style.cursor = previousCursor;
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
  };

  const autoFitColumn = (column: EventColumn, event: ReactMouseEvent<HTMLDivElement>) => {
    if (window.matchMedia("(max-width: 720px)").matches) return;
    event.preventDefault();
    event.stopPropagation();
    const list = listRef.current;
    if (!list) return;
    const row = list.querySelector<HTMLElement>(".event-row");
    const context = document.createElement("canvas").getContext("2d");
    if (!context) return;
    context.font = getComputedStyle(row ?? list).font;
    const widest = renderedEvents.slice(0, AUTO_FIT_SAMPLE_SIZE).reduce((max, item) => Math.max(max, context.measureText(eventColumnText(item, column)).width), 0);
    const limits = EVENT_COLUMN_LIMITS[column];
    applyColumnWidths({ ...columnWidths, [column]: clamp(Math.ceil(widest) + 12, limits.min, limits.max) });
  };

  const captureLocalSelectionAnchor = (event: EventLogItem) => {
    const list = listRef.current;
    const row = eventRowRefs.current.get(event.id);
    if (!list || !row) return;
    localSelectionScrollAnchorRef.current = {
      eventId: event.id,
      scrollTop: list.scrollTop,
      rowOffset: row.getBoundingClientRect().top - list.getBoundingClientRect().top
    };
  };

  const syncEventTime = (event: EventLogItem, callback: ((timeSec: number) => void) | undefined) => {
    if (!callback) return;
    captureLocalSelectionAnchor(event);
    locallySelectedEventIdRef.current = event.id;
    setLocalSelectionSnapshot({ events: visibleEvents, tab, query: normalizedQuery, eventsRange });
    callback(event.time);
  };

  const selectEvent = (event: EventLogItem) => {
    captureLocalSelectionAnchor(event);
    setSelectedEvent(event);
    if (syncTimeOnRowClick) syncEventTime(event, onSelectTime);
  };

  return (
    <section className={`events-card ${showHeader ? "" : "events-card-embedded"}`}>
      {showHeader && (
        <div className="pane-header events-header">
          <div className="pane-header-title-with-icon"><Icon className="pane-header-icon" name="events" size={14} /><h3>Events</h3></div>
          <div className="events-actions">
            {showSearch && <SearchInput className="event-search" value={query} onChange={setQuery} placeholder="Search events" label="event search" />}
            <label className="detail-range-select" title="Event range">
              <span>Range</span>
              <select value={eventsRange} onChange={(event) => onChangeEventsRange(event.target.value)}>
                <option value="24h">24h</option>
                <option value="12h">12h</option>
                <option value="6h">6h</option>
                <option value="3h">3h</option>
                <option value="1h">1h</option>
                <option value="30m">30m</option>
                <option value="10m">10m</option>
                <option value="5m">5m</option>
              </select>
            </label>
            <div className="events-tabs">
              <button className={tab === "all" ? "active" : ""} onClick={() => setTab("all")}>All</button>
              <button className={tab === "selected" ? "active" : ""} onClick={() => setTab("selected")}>Selected</button>
            </div>
          </div>
        </div>
      )}
      <div className={`events-content ${selectedEvent ? "has-context" : ""}`}>
        <div ref={listFrameRef} className="events-list-frame" style={columnStyle}>
          <div
            ref={listRef}
            className="events-list"
            onScroll={(event) => {
              const element = event.currentTarget;
              followLatestRef.current = element.scrollTop <= 8;
              scrollSnapshotRef.current = { top: element.scrollTop, height: element.scrollHeight };
            }}
          >
            {renderedEvents.length === 0 ? (
              <div className="events-empty">No events</div>
            ) : (
              <>
                {visibleEvents.length > MAX_RENDERED_EVENTS && <div className="events-empty">Showing latest {MAX_RENDERED_EVENTS} / {visibleEvents.length} events</div>}
                {renderedEvents.map((event) => (
                  <EventRow
                    key={event.id}
                    event={event}
                    primarySelected={primarySelectedEventId === event.id}
                    timeNeighbor={selectedTimeSec !== null && Math.abs(event.time - selectedTimeSec) < 0.5 && primarySelectedEventId !== event.id}
                    syncTimeOnSelect={syncTimeOnRowClick && onSelectTime !== undefined}
                    onSelect={() => selectEvent(event)}
                    eventRef={(element) => {
                      if (element) eventRowRefs.current.set(event.id, element);
                      else eventRowRefs.current.delete(event.id);
                    }}
                  />
                ))}
              </>
            )}
          </div>
          <EventColumnResizers widths={effectiveColumnWidths} onResizeStart={resizeColumn} onAutoFit={autoFitColumn} />
        </div>
        {selectedEvent && <EventContext
          event={selectedEvent}
          onSyncTime={onSyncTime ? () => syncEventTime(selectedEvent, onSyncTime) : undefined}
          onClose={() => {
            locallySelectedEventIdRef.current = null;
            lastAutoScrolledKeyRef.current = null;
            setLocalSelectionSnapshot(null);
            setSelectedEvent(null);
          }}
        />}
      </div>
    </section>
  );
}

function EventColumnResizers({
  widths,
  onResizeStart,
  onAutoFit
}: {
  widths: EventColumnWidths;
  onResizeStart: (column: EventColumn, event: ReactPointerEvent<HTMLDivElement>) => void;
  onAutoFit: (column: EventColumn, event: ReactMouseEvent<HTMLDivElement>) => void;
}) {
  const left = EVENT_ROW_SIDE_PADDING_PX + widths.time + EVENT_COLUMN_GAP_PX / 2;
  const boundaries: Array<{ column: EventColumn; left: number; label: string }> = [
    { column: "time", left, label: "Resize time column" },
    { column: "level", left: left + EVENT_COLUMN_GAP_PX / 2 + widths.level + EVENT_COLUMN_GAP_PX / 2, label: "Resize level column" },
    { column: "target", left: left + EVENT_COLUMN_GAP_PX / 2 + widths.level + EVENT_COLUMN_GAP_PX + widths.target + EVENT_COLUMN_GAP_PX / 2, label: "Resize target column" }
  ];
  return <div className="event-column-resizers">{boundaries.map(({ column, left: offset, label }) => (
    <div
      key={column}
      className="event-column-resizer"
      style={{ left: offset }}
      role="separator"
      aria-orientation="vertical"
      aria-label={`${label}; double-click to fit content`}
      title={`${label}. Double-click to fit content.`}
      onPointerDown={(event) => onResizeStart(column, event)}
      onDoubleClick={(event) => onAutoFit(column, event)}
    />
  ))}</div>;
}

function EventRow({ event, primarySelected, timeNeighbor, onSelect, eventRef, syncTimeOnSelect }: { event: EventLogItem; primarySelected: boolean; timeNeighbor: boolean; onSelect: () => void; eventRef: (element: HTMLButtonElement | null) => void; syncTimeOnSelect: boolean }) {
  const timeLabel = formatEventTime(event.time);
  const targetLabel = event.targetLabel ?? event.proto ?? event.scope;
  return (
    <button ref={eventRef} type="button" className={`event-row ${event.level}${primarySelected ? " event-primary-selected" : ""}${timeNeighbor ? " time-neighbor" : ""}`} onClick={onSelect} title={syncTimeOnSelect ? "Inspect this event and sync its timestamp" : "Inspect this event"} aria-current={primarySelected ? "true" : undefined}>
      <time className="event-time" dateTime={new Date(event.time * 1000).toISOString()} title={timeLabel}>{timeLabel}</time>
      <span className="event-level" title={event.level}>{event.level}</span>
      <span className="event-target" title={targetLabel}>{targetLabel}</span>
      <span className="event-message" title={event.message}>{event.message}</span>
    </button>
  );
}

function EventContext({ event, onClose, onSyncTime }: { event: EventLogItem; onClose: () => void; onSyncTime?: () => void }) {
  return (
    <aside className="event-context" aria-label="Selected event detail">
      <div className="event-context-header">
        <strong>Event detail</strong>
        <div className="event-context-actions">
          {onSyncTime && <button type="button" className="event-context-sync" onClick={onSyncTime} title="Set Dashboard time to this event">Sync time</button>}
          <button type="button" onClick={onClose} aria-label="Close event detail" title="Close event detail"><Icon name="close" size={16} /></button>
        </div>
      </div>
      <dl>
        <dt>Time</dt><dd>{formatEventTime(event.time)}</dd>
        <dt>Level</dt><dd>{event.level}</dd>
        <dt>Type</dt><dd>{event.type}</dd>
        <dt>Target</dt><dd>{event.targetLabel ?? event.proto ?? event.scope}</dd>
      </dl>
      <p>{event.message}</p>
      {event.detail !== undefined && <pre>{JSON.stringify(event.detail, null, 2)}</pre>}
    </aside>
  );
}


function closestEventWithin(events: EventLogItem[], selectedTimeSec: number | null) {
  if (selectedTimeSec === null) return null;
  return events.reduce<EventLogItem | null>((closest, event) => {
    const distance = Math.abs(event.time - selectedTimeSec);
    if (distance >= 0.5) return closest;
    if (!closest || distance < Math.abs(closest.time - selectedTimeSec)) return event;
    return closest;
  }, null);
}
export function parseEventColumnWidths(value: unknown): EventColumnWidths | undefined {
  let parsed = value;
  if (typeof value === "string") {
    try { parsed = JSON.parse(value); } catch { return undefined; }
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return undefined;
  const candidate = parsed as Partial<EventColumnWidths>;
  if (![candidate.time, candidate.level, candidate.target].every((width) => typeof width === "number" && Number.isFinite(width))) return undefined;
  return normalizeColumnWidths(candidate as EventColumnWidths);
}

function loadStoredColumnWidths() {
  try { return parseEventColumnWidths(window.localStorage.getItem(EVENT_LIST_STORAGE_KEY)) ?? DEFAULT_EVENT_COLUMN_WIDTHS; }
  catch { return DEFAULT_EVENT_COLUMN_WIDTHS; }
}

function normalizeColumnWidths(widths: EventColumnWidths) {
  return {
    time: clamp(widths.time, EVENT_COLUMN_LIMITS.time.min, EVENT_COLUMN_LIMITS.time.max),
    level: clamp(widths.level, EVENT_COLUMN_LIMITS.level.min, EVENT_COLUMN_LIMITS.level.max),
    target: clamp(widths.target, EVENT_COLUMN_LIMITS.target.min, EVENT_COLUMN_LIMITS.target.max)
  };
