367	  onAutoFit
368	}: {
369	  widths: EventColumnWidths;
370	  onResizeStart: (column: EventColumn, event: ReactPointerEvent<HTMLDivElement>) => void;
371	  onAutoFit: (column: EventColumn, event: ReactMouseEvent<HTMLDivElement>) => void;
372	}) {
373	  const left = EVENT_ROW_SIDE_PADDING_PX + widths.time + EVENT_COLUMN_GAP_PX / 2;
374	  const boundaries: Array<{ column: EventColumn; left: number; label: string }> = [
375	    { column: "time", left, label: "Resize time column" },
376	    { column: "level", left: left + EVENT_COLUMN_GAP_PX / 2 + widths.level + EVENT_COLUMN_GAP_PX / 2, label: "Resize level column" },
377	    { column: "target", left: left + EVENT_COLUMN_GAP_PX / 2 + widths.level + EVENT_COLUMN_GAP_PX + widths.target + EVENT_COLUMN_GAP_PX / 2, label: "Resize target column" }
378	  ];
379	  return <div className="event-column-resizers">{boundaries.map(({ column, left: offset, label }) => (
380	    <div
381	      key={column}
382	      className="event-column-resizer"
383	      style={{ left: offset }}
384	      role="separator"
385	      aria-orientation="vertical"
386	      aria-label={`${label}; double-click to fit content`}
387	      title={`${label}. Double-click to fit content.`}
388	      onPointerDown={(event) => onResizeStart(column, event)}
389	      onDoubleClick={(event) => onAutoFit(column, event)}
390	    />
391	  ))}</div>;
