output.text:
.events-card {
  display: grid;
  grid-template-rows: var(--pane-header-height) minmax(0, 1fr);
  gap: 0;
  padding: 0;
  border-radius: var(--radius-md);
  overflow: hidden;
}

.events-card-embedded {
  grid-template-rows: minmax(0, 1fr);
}

.events-header {
  min-width: 0;
  margin: 0;
  padding: 0 var(--space-2);
  border-bottom: 1px solid var(--line);
}

.events-header h3 {
  flex: 0 0 auto;
}

.events-actions {
  gap: 6px;
}

.event-search {
  width: min(260px, 30vw);
}

.events-tabs button {
  min-width: 48px;
  min-height: 24px;
  padding: 0 7px;
  font-size: var(--font-size-xs);
}

.events-content {
  min-height: 0;
  display: grid;
  grid-template-rows: minmax(0, 1fr);
}

.events-content.has-context {
  grid-template-rows: minmax(0, 1fr) minmax(138px, auto);
}

.events-list-frame {
  position: relative;
  min-height: 0;
  height: 100%;
  overflow: hidden;
}

.events-list {
  min-height: 0;
  height: 100%;
  max-height: none;
  overflow: auto;
  gap: 0;
  padding: var(--space-1);
  background: var(--surface);
}

.event-row {
  min-height: 30px;
  height: 30px;
  grid-template-columns: var(--event-time-width) var(--event-level-width) var(--event-target-width) minmax(0, 1fr);
  column-gap: 4px;
  row-gap: 0;
  padding: 0 var(--space-2);
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 72%, transparent);
  border-radius: 0;
  background: transparent;
  color: var(--text);
  font-size: var(--font-size-xs);
}

.event-column-resizers {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
}

.event-column-resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 10px;
  transform: translateX(-50%);
  cursor: col-resize;
  pointer-events: auto;
  touch-action: none;
}

.event-column-resizer::before {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 4px;
  width: 1px;
  background: transparent;
  content: "";
}

.event-column-resizer:hover::before,
.event-column-resizer:active::before {
  background: var(--accent);
}

.event-time, .event-level, .event-target, .event-message {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.event-row:hover {
  background: var(--surface-muted);
}

.event-row.time-neighbor {
  background: color-mix(in srgb, var(--accent-soft) 58%, var(--surface));
}

.event-row.time-neighbor:hover {
  background: color-mix(in srgb, var(--accent-soft) 76%, var(--surface));
}

.event-row.event-primary-selected {
  background: var(--accent-soft);
  box-shadow: inset 4px 0 0 var(--accent);
}

.event-row.event-primary-selected .event-time {
  color: var(--text-strong);
  font-weight: 700;
}

.event-time {
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.event-level {
  width: fit-content;
  padding: 2px 4px;
  border-radius: var(--radius-sm);
  background: var(--success-soft);
  color: var(--success);
  font-size: 10px;
  line-height: 1;
}

.event-row.warn .event-level {
  background: var(--warning-soft);
  color: var(--warning);
}

.event-row.error .event-level {
  background: var(--danger-soft);
  color: var(--danger);
}

.event-context {
  min-height: 0;
  padding: var(--space-2) var(--space-3);
  border-top: 1px solid var(--line);
  background: var(--surface-muted);
  overflow: auto;
}

.event-context-inline {
  max-height: min(220px, 45vh);
  border-top-color: var(--accent-border);
  border-bottom: 1px solid var(--line);
}

.event-context-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  margin-bottom: var(--space-2);
}

.event-context-header strong {
  color: var(--text-strong);
  font-size: var(--font-size-sm);
}

.event-context-header button {
  min-height: 22px;
  width: 22px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 18px;
}

.event-context-actions {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.event-context-header .event-context-sync {
  width: auto;
  padding: 0 var(--space-2);
  border: 1px solid var(--line);
  background: var(--surface);
  color: var(--text);
  font-size: var(--font-size-xs);
}

.event-context-header .event-context-sync:hover {
  border-color: var(--accent-border);
  color: var(--accent);
}

.event-context dl {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  gap: 4px var(--space-2);
  margin: 0;
  font-size: var(--font-size-xs);
}

.event-context dt { color: var(--muted); }
.event-context dd { min-width: 0; margin: 0; overflow-wrap: anywhere; color: var(--text-strong); }
.event-context p { margin: var(--space-2) 0; font-size: var(--font-size-sm); }
.event-context pre { margin: 0; color: var(--muted); font: 11px/1.35 ui-monospace, SFMono-Regular, Menlo, monospace; white-space: pre-wrap; overflow-wrap: anywhere; }

@media (min-width: 1100px) {
  .standalone-events .events-content.has-context {
    grid-template-columns: minmax(0, 1fr) minmax(260px, 320px);
    grid-template-rows: minmax(0, 1fr);
  }

  .standalone-events .event-context {
    border-top: 0;
    border-left: 1px solid var(--line);
  }
}

@media (max-width: 720px) {
  .events-header { align-items: center; }
  .event-search { width: min(160px, 40vw); }
  .events-tabs { display: none; }
  .event-row { grid-template-columns: 145px 42px minmax(0, 1fr); }
  .event-message { display: none; }
  .event-column-resizers { display: none; }
}

/* Standalone events uses the shared 36px header/body division. */
.main-tab-events .standalone-events {
  min-height: 0;
  height: 100%;
  display: grid;
}

.main-tab-events .events-card {
  min-height: 0;
  height: 100%;
  margin: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.main-tab-events .events-header {
  min-height: var(--pane-header-height);
  margin: 0;
  padding: 0 var(--space-2);
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  background: var(--surface);
}
