.dashboard-cell-header input,
.dashboard-cell-header select {
  min-height: 24px;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-xs);
  padding: 0 6px;
}

.dashboard-cell-body {
  background: var(--surface);
}

.dashboard-rgl-shell.is-editing .dashboard-cell {
  border-color: var(--accent-border);
}

.dashboard-rgl-shell.is-editing .react-grid-item.react-draggable-dragging .dashboard-cell {
  box-shadow: var(--shadow-md);
}

.dashboard-rgl-shell.is-editing .react-resizable-handle::after {
  border-color: var(--accent);
}

@media (max-width: 720px) {
  .dashboard-toolbar .pane-header-meta,
  .dashboard-toolbar .detail-range-select {
    display: none;
  }

  .dashboard-cell-search {
    width: min(140px, 36vw);
  }

  .dashboard-cell-actions .events-tabs {
    display: inline-flex;
  }
}

/* Compact cells keep their identity outside edit mode without recreating a card within a card. */
.dashboard-cell {
  min-height: 0;
  display: grid;
  grid-template-rows: 32px minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid var(--line);
}

.dashboard-cell-header.pane-header {
  min-height: 32px;
  height: 32px;
  padding: 0 var(--space-2);
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  background: var(--surface-muted);
}

.dashboard-cell-body {
  min-height: 0;
  overflow: hidden;
}

.dashboard-cell-body .events-card,
.dashboard-cell-body .detail-pane {
  border-radius: 0;
}


.dashboard-detail-target,
.dashboard-detail-target-mode {
  min-width: 0;
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
