    87	}: EventLogProps) {
    88	  const [internalTab, setInternalTab] = useState<EventLogTab>("all");
    89	  const [internalQuery, setInternalQuery] = useState(initialQuery);
    90	  const [internalColumnWidths, setInternalColumnWidths] = useState<EventColumnWidths>(loadStoredColumnWidths);
    91	  const [selectedEvent, setSelectedEvent] = useState<EventLogItem | null>(null);
    92	  const [localSelectionSnapshot, setLocalSelectionSnapshot] = useState<LocalSelectionSnapshot | null>(null);
    93	  const [listWidth, setListWidth] = useState(0);
    94	  const listRef = useRef<HTMLDivElement | null>(null);
    95	  const listFrameRef = useRef<HTMLDivElement | null>(null);
    96	  const scrollSnapshotRef = useRef({ top: 0, height: 0 });
    97	  const followLatestRef = useRef(true);
    98	  const eventRowRefs = useRef(new Map<string, HTMLButtonElement>());
    99	  const lastAutoScrolledKeyRef = useRef<string | null>(null);
   100	  const locallySelectedEventIdRef = useRef<string | null>(null);
   101	  const localSelectionScrollAnchorRef = useRef<LocalSelectionScrollAnchor | null>(null);
   102	  const tab = controlledTab ?? internalTab;
   103	  const setTab = onChangeTab ?? setInternalTab;
   104	  const query = controlledQuery ?? internalQuery;
   105	  const setQuery = onChangeQuery ?? setInternalQuery;
   106	  const columnWidths = normalizeColumnWidths(controlledColumnWidths ?? internalColumnWidths);
   107	  const scopedEvents = tab === "all" ? events : events.filter((event) => {
   108	    if (selectedFlowKey) return event.flowKey === selectedFlowKey || event.streamKey === selectedStreamKey;
   109	    if (selectedStreamKey) return event.streamKey === selectedStreamKey;
   110	    if (selectedInterfaceId !== null) return event.interfaceId === selectedInterfaceId;
   111	    return false;
   112	  });
   113	  const normalizedQuery = query.trim();
   114	  const matchingEvents = normalizedQuery ? scopedEvents.filter((event) => eventMatches(event, query)) : scopedEvents;
   115	  const visibleEvents = localSelectionSnapshot?.events ?? matchingEvents;
   116	  const renderedEvents = visibleEvents.slice(0, MAX_RENDERED_EVENTS);
   117	  const timeSelectedEvent = useMemo(() => closestEventWithin(renderedEvents, selectedTimeSec), [renderedEvents, selectedTimeSec]);
   118	  const primarySelectedEventId = selectedEvent && renderedEvents.some((event) => event.id === selectedEvent.id)
   119	    ? selectedEvent.id
   120	    : timeSelectedEvent?.id ?? null;
   121	  const visibleSignature = `${visibleEvents[0]?.id ?? ""}:${visibleEvents.length}:${visibleEvents[visibleEvents.length - 1]?.id ?? ""}`;
   122	  const effectiveColumnWidths = useMemo(() => fitColumnWidths(columnWidths, listWidth), [columnWidths, listWidth]);
   123	  const columnStyle = useMemo(() => ({
   124	    "--event-time-width": `${effectiveColumnWidths.time}px`,
   125	    "--event-level-width": `${effectiveColumnWidths.level}px`,
   126	    "--event-target-width": `${effectiveColumnWidths.target}px`
   127	  }) as CSSProperties, [effectiveColumnWidths]);
   128	
   129	  useLayoutEffect(() => {
   130	    const element = listFrameRef.current;
   131	    if (!element) return;
   132	    const update = () => setListWidth(element.clientWidth);
   133	    update();
   134	    const observer = new ResizeObserver(update);
   135	    observer.observe(element);
   136	    return () => observer.disconnect();
   137	  }, []);
   138	
   139	  useLayoutEffect(() => {
   140	    const snapshot = localSelectionSnapshot;
   141	    if (!snapshot) return;
   142	    const selectionIsCurrent = selectedEvent !== null
   143	      && selectedTimeSec === selectedEvent.time
   144	      && snapshot.tab === tab
   145	      && snapshot.query === normalizedQuery
   146	      && snapshot.eventsRange === eventsRange;
   147	    if (selectionIsCurrent) return;
   148	    setLocalSelectionSnapshot(null);
   149	  }, [eventsRange, localSelectionSnapshot, normalizedQuery, selectedEvent, selectedTimeSec, tab]);
   150	
   151	  useLayoutEffect(() => {
   152	    const element = listRef.current;
   153	    if (!element || visibleEvents.length === 0) return;
   154	    const prev = scrollSnapshotRef.current;
   155	    const heightDelta = element.scrollHeight - prev.height;
   156	    if (!followLatestRef.current && heightDelta !== 0) element.scrollTop = prev.top + heightDelta;
   157	    scrollSnapshotRef.current = { top: element.scrollTop, height: element.scrollHeight };
   158	  }, [visibleSignature, tab, normalizedQuery, eventsRange, visibleEvents.length]);
