.events-content.has-context {
  grid-template-rows: minmax(0, 1fr) minmax(138px, auto);
}

.events-list-frame {
  position: relative;
  min-height: 0;
  height: 100%;
  overflow: hidden;
}

.events-list {
  min-height: 0;
  height: 100%;
  max-height: none;
  overflow: auto;
  gap: 0;
  padding: var(--space-1);
  background: var(--surface);
}

.event-row {
  min-height: 30px;
  height: 30px;
  grid-template-columns: var(--event-time-width) var(--event-level-width) var(--event-target-width) minmax(0, 1fr);
  column-gap: 4px;
  row-gap: 0;
  padding: 0 var(--space-2);
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 72%, transparent);
  border-radius: 0;
  background: transparent;
  color: var(--text);
  font-size: var(--font-size-xs);
}

.event-column-resizers {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
}

.event-column-resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 10px;
  transform: translateX(-50%);
  cursor: col-resize;
  pointer-events: auto;
  touch-action: none;
}

.event-column-resizer::before {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 4px;
  width: 1px;
