export type EventLogItem = {
  id: string;
  time: number;
  type: string;
  level: "info" | "warn" | "error";
  scope: "system" | "stream" | "flow";
  proto?: string;
  interfaceId?: number;
  streamKey?: string;
  flowKey?: string;
  targetLabel?: string;
  message: string;
  detail?: unknown;
};

export type TopologyAlertSummary = {
  state?: string;
  severity?: string;
  count?: number;
  alerts?: unknown[];
};
import type { EventLogItem } from "./types";

type AnyRecord = Record<string, any>;

export function normalizeEventLine(line: string): EventLogItem | undefined {
  const raw = JSON.parse(line) as AnyRecord;
  const time = Number(raw.time ?? Date.now() / 1000);
  const type = String(raw.type ?? "event");
  const source = raw.source ?? {};
  const detail = raw.detail;
  const streamKey = source.stream_key ? String(source.stream_key) : undefined;
  const flowKey = source.flow_key ? String(source.flow_key) : undefined;
  const proto = source.proto ? String(source.proto) : undefined;
  const interfaceId = numericInterfaceId(source.interface_id) ?? interfaceIdFromKey(flowKey) ?? interfaceIdFromKey(streamKey);
  return {
    id: typeof raw.record_id === "string" && raw.record_id ? raw.record_id : `${time}:${type}:${streamKey ?? "system"}:${flowKey ?? ""}`,
    time,
    type,
    level: levelForType(type),
    scope: flowKey ? "flow" : streamKey ? "stream" : "system",
    proto,
    interfaceId,
    streamKey,
    flowKey,
    targetLabel: targetLabel(source, streamKey, flowKey, detail),
    message: messageForType(type),
    detail
  };
}

function levelForType(type: string): EventLogItem["level"] {
  if (/error|failed|failure/i.test(type)) return "error";
  if (/warn|stale|drop|loss|timeout/i.test(type)) return "warn";
  return "info";
}

function messageForType(type: string) {
  return type
    .split("_")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

function targetLabel(source: AnyRecord, streamKey?: string, flowKey?: string, detail?: AnyRecord) {
  if (!streamKey && !flowKey) return "System";

  const scope = recordValue(source.scope);
  const nic = stringValue(scope?.interface_name) ?? stringValue(source.interface_name) ?? interfaceLabel(source.interface_id);
  const vlan = vlanLabel(scope?.vlan ?? source.vlan, scope);
  const endpoint = endpointLabel(detail?.endpoint, flowKey, streamKey);
  return [nic, vlan, stringValue(source.proto), endpoint].filter((part): part is string => Boolean(part)).join(" · ") || "Stream";
}

function endpointLabel(detailEndpoint: unknown, flowKey?: string, streamKey?: string) {
  const endpoint = recordValue(detailEndpoint);
  const src = stringValue(endpoint?.src) ?? keyField(flowKey, "src");
  const dst = stringValue(endpoint?.dst) ?? keyField(flowKey, "dst");
  if (src && dst) return `${src} → ${dst}`;

  const a = stringValue(endpoint?.a) ?? keyField(streamKey, "a");
  const b = stringValue(endpoint?.b) ?? keyField(streamKey, "b");
  if (a && b) return `${a} → ${b}`;

  return stringValue(endpoint?.service)
    ?? stringValue(endpoint?.session_dst)
    ?? keyField(streamKey, "session_dst")
    ?? keyField(streamKey, "ep")
    ?? dst
    ?? src;
}

function vlanLabel(vlan: unknown, scope?: AnyRecord) {
  const layers = Array.isArray(scope?.layers) ? scope.layers : [];
  const vlanLayer = layers.map(recordValue).find((layer) => layer?.kind === "vlan");
  const vlanId = stringValue(vlanLayer?.id) ?? valueText(recordValue(vlan)?.id) ?? valueText(vlan);
  if (vlanId) return `VLAN ${vlanId}`;
  if (vlan === null || scope !== undefined || layers.length > 0) return "Untagged";
  return "VLAN unknown";
}

function keyField(key: string | undefined, field: string) {
  if (!key) return undefined;
  const prefix = `${field}=`;
  const value = key.split("|").find((part) => part.startsWith(prefix))?.slice(prefix.length);
  return value || undefined;
}

function interfaceLabel(value: unknown) {
  const id = numericInterfaceId(value);
  return id === undefined ? "NIC unknown" : `if:${id}`;
}

function numericInterfaceId(value: unknown) {
  const number = typeof value === "number" ? value : typeof value === "string" ? Number(value) : Number.NaN;
  return Number.isInteger(number) ? number : undefined;
}

function recordValue(value: unknown): AnyRecord | undefined {
  return value && typeof value === "object" && !Array.isArray(value) ? value as AnyRecord : undefined;
}

function stringValue(value: unknown) {
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

function valueText(value: unknown) {
  return typeof value === "string" || typeof value === "number" ? String(value) : undefined;
}

function interfaceIdFromKey(key?: string) {
  const match = key?.match(/(?:^|\|)if=(\d+)/);
  return match ? Number(match[1]) : undefined;
}
