import { createReadStream, existsSync, readdirSync } from "node:fs";
import path from "node:path";
import readline from "node:readline";
import { config } from "../config";
import { normalizeEventLine } from "../events";
import type { EventLogItem } from "../types";

type QueryOptions = {
  from: number;
  to: number;
  streamKey?: string;
  flowKey?: string;
  interfaceId?: number;
  proto?: string;
  level?: EventLogItem["level"];
  type?: string;
  limit?: number;
};

export type OverviewEventCounts = {
  streams: ReadonlyMap<string, number>;
  flows: ReadonlyMap<string, number>;
  streamOnly: ReadonlyMap<string, number>;
};

/** Counts warning and error events without materializing the event range in memory. */
export async function queryOverviewEventCounts(options: Pick<QueryOptions, "from" | "to">): Promise<OverviewEventCounts> {
  const streams = new Map<string, number>();
  const flows = new Map<string, number>();
  const streamOnly = new Map<string, number>();

  for (const file of listEventFiles(options.from, options.to)) {
    const input = readline.createInterface({ input: createReadStream(file), crlfDelay: Infinity });
    for await (const line of input) {
      if (!line) continue;
      let event: EventLogItem | undefined;
      try {
        event = normalizeEventLine(line);
      } catch {
        event = undefined;
      }
      if (!event || event.time < options.from || event.time > options.to) continue;
      if (event.level !== "warn" && event.level !== "error") continue;
      if (!event.streamKey) continue;
      incrementCount(streams, event.streamKey);
      if (event.flowKey) incrementCount(flows, event.flowKey);
      else incrementCount(streamOnly, event.streamKey);
    }
  }

  return { streams, flows, streamOnly };
}

export async function queryEventsHistory(options: QueryOptions): Promise<EventLogItem[]> {
  const keep = Number.isFinite(options.limit) && (options.limit ?? 0) > 0
    ? Math.floor(options.limit as number)
    : Number.POSITIVE_INFINITY;

  const matched: EventLogItem[] = [];
  const files = listEventFiles(options.from, options.to);
  if (config.eventsQueryDebugLog) {
    console.error(`[EVENTS_QUERY] files=${files.length} from=${options.from} to=${options.to}`);
    for (const file of files) {
      console.error(`[EVENTS_QUERY] file=${file}`);
    }
  }
  let scanned = 0;
  let filtered = 0;

  for (const file of files) {
    let fileScanned = 0;
    let fileMatched = 0;
    const rl = readline.createInterface({
      input: createReadStream(file),
      crlfDelay: Infinity
    });

    for await (const line of rl) {
      scanned += 1;
      fileScanned += 1;
      if (!line) continue;
      let event: EventLogItem | undefined;
      try {
        event = normalizeEventLine(line);
      } catch {
        event = undefined;
      }
      if (!event) continue;
      if (event.time < options.from || event.time > options.to) continue;
      if (options.streamKey && event.streamKey !== options.streamKey) continue;
