  const closeSelectedEvent = () => {
    locallySelectedEventIdRef.current = null;
    keyboardSelectionEventIdRef.current = null;
    lastAutoScrolledKeyRef.current = null;
    setLocalSelectionSnapshot(null);
    setSelectedEvent(null);
  };

  const syncEventTime = (event: EventLogItem, callback: ((timeSec: number) => void) | undefined) => {
    if (!callback) return;
    captureLocalSelectionAnchor(event);
    locallySelectedEventIdRef.current = event.id;
    setLocalSelectionSnapshot({ events: visibleEvents, tab, query: normalizedQuery, eventsRange });
    callback(event.time);
  };

  const selectEvent = (event: EventLogItem) => {
    captureLocalSelectionAnchor(event);
    setSelectedEvent(event);
    if (syncTimeOnRowClick) syncEventTime(event, onSelectTime);
  };

  const moveEventSelection = (event: EventLogItem, direction: -1 | 1) => {
    const currentEventId = keyboardSelectionEventIdRef.current ?? event.id;
    const index = renderedEvents.findIndex((item) => item.id === currentEventId);
    const nextEvent = index === -1 ? undefined : renderedEvents[index + direction];
    if (!nextEvent) return;
    keyboardSelectionEventIdRef.current = nextEvent.id;
    selectEvent(nextEvent);
  };

  return (
    <section className={`events-card ${showHeader ? "" : "events-card-embedded"}`}>
      {showHeader && (
        <div className="pane-header events-header">
          <div className="pane-header-title-with-icon"><Icon className="pane-header-icon" name="events" size={14} /><h3>Events</h3></div>
          <div className="events-actions">
            {showSearch && <SearchInput className="event-search" value={query} onChange={setQuery} placeholder="Search events" label="event search" />}
            <label className="detail-range-select" title="Event range">
              <span>Range</span>
              <select value={eventsRange} onChange={(event) => onChangeEventsRange(event.target.value)}>
                <option value="24h">24h</option>
                <option value="12h">12h</option>
                <option value="6h">6h</option>
                <option value="3h">3h</option>
                <option value="1h">1h</option>
                <option value="30m">30m</option>
                <option value="10m">10m</option>
                <option value="5m">5m</option>
              </select>
            </label>
            <div className="events-tabs">
              <button className={tab === "all" ? "active" : ""} onClick={() => setTab("all")}>All</button>
              <button className={tab === "selected" ? "active" : ""} onClick={() => setTab("selected")}>Selected</button>
            </div>
          </div>
        </div>
      )}
      <div className={`events-content ${detailPresentation === "panel" && selectedEvent ? "has-context" : ""}`}>
        <div ref={listFrameRef} className="events-list-frame" style={columnStyle}>
          <div
            ref={listRef}
            className="events-list"
            onScroll={(event) => {
              const element = event.currentTarget;
              followLatestRef.current = element.scrollTop <= 8;
              setShowLatestJump(element.scrollTop > 8);
              scrollSnapshotRef.current = { top: element.scrollTop, height: element.scrollHeight };
            }}
          >
            {renderedEvents.length === 0 ? (
              <div className="events-empty">No events</div>
            ) : (
              <>
                {visibleEvents.length > MAX_RENDERED_EVENTS && <div className="events-empty">Showing latest {MAX_RENDERED_EVENTS} / {visibleEvents.length} events</div>}
                {renderedEvents.map((event) => {
                  const isRelatedEvent = activeRelatedEvent?.id === event.id;
                  return <Fragment key={event.id}>
                    {isRelatedEvent && relatedEventOutsideRange && <div className="event-related-boundary">Related event outside current range</div>}
                    <EventRow
                      event={event}
                      primarySelected={primarySelectedEventId === event.id}
                      related={isRelatedEvent}
                      timeNeighbor={selectedTimeSec !== null && Math.abs(event.time - selectedTimeSec) < 0.5 && primarySelectedEventId !== event.id}
                      syncTimeOnSelect={syncTimeOnRowClick && onSelectTime !== undefined}
                      onSelect={() => selectEventFromPointer(event)}
                      onMoveSelection={(direction) => moveEventSelection(event, direction)}
                      eventRef={(element) => {
                        if (element) eventRowRefs.current.set(event.id, element);
                        else eventRowRefs.current.delete(event.id);
                      }}
                    />
                    {detailPresentation === "inline" && selectedEvent?.id === event.id && <EventContext
                      event={selectedEvent}
                      inline
                      relatedEvent={activeRelatedEvent}
                      relatedOutsideRange={relatedEventOutsideRange}
                      onSelectRelated={activeRelatedEvent ? () => selectEventFromPointer(activeRelatedEvent) : undefined}
                      onSyncTime={onSyncTime ? () => syncEventTime(selectedEvent, onSyncTime) : undefined}
                      onClose={closeSelectedEvent}
                    />}
                  </Fragment>;
                })}
              </>
            )}
          </div>
          {showLatestJump && <button type="button" className="events-jump-latest" onClick={jumpToLatest} title="Jump to latest event">Latest</button>}
          <EventColumnResizers widths={effectiveColumnWidths} onResizeStart={resizeColumn} onAutoFit={autoFitColumn} />
        </div>
        {detailPresentation === "panel" && selectedEvent && <EventContext
          event={selectedEvent}
          relatedEvent={activeRelatedEvent}
          relatedOutsideRange={relatedEventOutsideRange}
          onSelectRelated={activeRelatedEvent ? () => selectEventFromPointer(activeRelatedEvent) : undefined}
          onSyncTime={onSyncTime ? () => syncEventTime(selectedEvent, onSyncTime) : undefined}
          onClose={closeSelectedEvent}
        />}
      </div>
    </section>
  );
}

function EventColumnResizers({
  widths,
  onResizeStart,
  onAutoFit
}: {
  widths: EventColumnWidths;
  onResizeStart: (column: EventColumn, event: ReactPointerEvent<HTMLDivElement>) => void;
  onAutoFit: (column: EventColumn, event: ReactMouseEvent<HTMLDivElement>) => void;
}) {
  const left = EVENT_ROW_SIDE_PADDING_PX + widths.time + EVENT_COLUMN_GAP_PX / 2;
  const boundaries: Array<{ column: EventColumn; left: number; label: string }> = [
    { column: "time", left, label: "Resize time column" },
    { column: "level", left: left + EVENT_COLUMN_GAP_PX / 2 + widths.level + EVENT_COLUMN_GAP_PX / 2, label: "Resize level column" },
    { column: "target", left: left + EVENT_COLUMN_GAP_PX / 2 + widths.level + EVENT_COLUMN_GAP_PX + widths.target + EVENT_COLUMN_GAP_PX / 2, label: "Resize target column" }
  ];
  return <div className="event-column-resizers">{boundaries.map(({ column, left: offset, label }) => (
    <div
      key={column}
      className="event-column-resizer"
      style={{ left: offset }}
      role="separator"
      aria-orientation="vertical"
      aria-label={`${label}; double-click to fit content`}
      title={`${label}. Double-click to fit content.`}
      onPointerDown={(event) => onResizeStart(column, event)}
      onDoubleClick={(event) => onAutoFit(column, event)}
    />
  ))}</div>;
}

function EventRow({ event, primarySelected, related, timeNeighbor, onSelect, onMoveSelection, eventRef, syncTimeOnSelect }: { event: EventLogItem; primarySelected: boolean; related: boolean; timeNeighbor: boolean; onSelect: () => void; onMoveSelection: (direction: -1 | 1) => void; eventRef: (element: HTMLButtonElement | null) => void; syncTimeOnSelect: boolean }) {
  const timeLabel = formatEventTime(event.time);
  const targetLabel = event.targetLabel ?? event.proto ?? event.scope;
  const onKeyDown = (keyEvent: ReactKeyboardEvent<HTMLButtonElement>) => {
    const direction = keyEvent.key === "ArrowUp" ? -1 : keyEvent.key === "ArrowDown" ? 1 : null;
    if (direction === null) return;
    keyEvent.preventDefault();
    onMoveSelection(direction);
  };
  return (
    <button ref={eventRef} type="button" className={`event-row ${event.level}${primarySelected ? " event-primary-selected" : ""}${related ? " event-related" : ""}${timeNeighbor ? " time-neighbor" : ""}`} onClick={onSelect} onKeyDown={onKeyDown} title={syncTimeOnSelect ? "Inspect this event and sync its timestamp. Use Up/Down to select adjacent events." : "Inspect this event. Use Up/Down to select adjacent events."} aria-current={primarySelected ? "true" : undefined} aria-keyshortcuts="ArrowUp ArrowDown">
      <time className="event-time" dateTime={new Date(event.time * 1000).toISOString()} title={timeLabel}>{timeLabel}</time>
      <span className="event-level" title={event.level}>{event.level}</span>
      <span className="event-target" title={targetLabel}>{targetLabel}</span>
      <span className="event-message" title={event.message}>{event.message}</span>
    </button>
  );
}

function EventContext({ event, onClose, onSyncTime, relatedEvent, relatedOutsideRange = false, onSelectRelated, inline = false }: { event: EventLogItem; onClose: () => void; onSyncTime?: () => void; relatedEvent?: EventLogItem | null; relatedOutsideRange?: boolean; onSelectRelated?: () => void; inline?: boolean }) {
  return (
    <aside className={`event-context${inline ? " event-context-inline" : ""}`} aria-label="Selected event detail">
      <div className="event-context-header">
        <strong>Event detail</strong>
        <div className="event-context-actions">
          {onSyncTime && <button type="button" className="event-context-sync" onClick={onSyncTime} title="Set Dashboard time to this event">Sync time</button>}
          <button type="button" onClick={onClose} aria-label="Close event detail" title="Close event detail"><Icon name="close" size={16} /></button>
        </div>
      </div>
      <dl>
        <dt>Time</dt><dd>{formatEventTime(event.time)}</dd>
        <dt>Level</dt><dd>{event.level}</dd>
        <dt>Type</dt><dd>{event.type}</dd>
        <dt>Target</dt><dd>{event.targetLabel ?? event.proto ?? event.scope}</dd>
      </dl>
      {relatedEvent && onSelectRelated && <div className="event-context-related">
        <span>Related event</span>
        <button type="button" onClick={onSelectRelated} title="Select related event">{relatedEvent.message} · {formatEventTime(relatedEvent.time)}</button>
        {relatedOutsideRange && <small>Outside current range</small>}
      </div>}
      <p>{event.message}</p>
      {event.detail !== undefined && <pre>{JSON.stringify(event.detail, null, 2)}</pre>}
    </aside>
  );
}


function eventRelationFor(event: EventLogItem): EventRelation | null {
  const lifecycle = event.type.match(/^(stream|flow)_(detected|recovered|lost)$/);
  if (lifecycle) {
    const [, subject, action] = lifecycle;
    if (action === "lost") return { counterpartTypes: [`${subject}_detected`, `${subject}_recovered`], direction: "before" };
    return { counterpartTypes: [`${subject}_lost`], direction: "after" };
  }
  if (event.type.endsWith("_occurred")) return { counterpartTypes: [`${event.type.slice(0, -"occurred".length)}recovered`], direction: "after" };
  if (event.type.endsWith("_recovered")) return { counterpartTypes: [`${event.type.slice(0, -"recovered".length)}occurred`], direction: "before" };
  return null;
}

function findRelatedEvent(events: EventLogItem[], source: EventLogItem, relation: EventRelation) {
  return events.reduce<EventLogItem | null>((closest, candidate) => {
    if (candidate.id === source.id || !relation.counterpartTypes.includes(candidate.type) || !sameRelationTarget(source, candidate)) return closest;
    if (relation.direction === "before" ? candidate.time >= source.time : candidate.time <= source.time) return closest;
    if (!closest || Math.abs(candidate.time - source.time) < Math.abs(closest.time - source.time)) return candidate;
    return closest;
  }, null);
}

function sameRelationTarget(source: EventLogItem, candidate: EventLogItem) {
  if (source.flowKey || candidate.flowKey) return Boolean(source.flowKey && source.flowKey === candidate.flowKey);
  return Boolean(source.streamKey && source.streamKey === candidate.streamKey);
}

function closestEventWithin(events: EventLogItem[], selectedTimeSec: number | null) {

