  };
  return (
    <button ref={eventRef} type="button" className={`event-row ${event.level}${primarySelected ? " event-primary-selected" : ""}${related ? " event-related" : ""}${timeNeighbor ? " time-neighbor" : ""}`} onClick={onSelect} onKeyDown={onKeyDown} title={syncTimeOnSelect ? "Inspect this event and sync its timestamp. Use Up/Down to select adjacent events." : "Inspect this event. Use Up/Down to select adjacent events."} aria-current={primarySelected ? "true" : undefined} aria-keyshortcuts="ArrowUp ArrowDown">
      <time className="event-time" dateTime={new Date(event.time * 1000).toISOString()} title={timeLabel}>{timeLabel}</time>
      <span className="event-level" title={event.level}>{event.level}</span>
      <span className="event-target" title={targetLabel}>{targetLabel}</span>
      <span className="event-message" title={event.message}>{event.message}</span>
    </button>
  );
}

function EventContext({ event, onClose, onSyncTime, relatedEvent, relatedOutsideRange = false, onSelectRelated, inline = false }: { event: EventLogItem; onClose: () => void; onSyncTime?: () => void; relatedEvent?: EventLogItem | null; relatedOutsideRange?: boolean; onSelectRelated?: () => void; inline?: boolean }) {
  return (
    <aside className={`event-context${inline ? " event-context-inline" : ""}`} aria-label="Selected event detail">
      <div className="event-context-header">
        <strong>Event detail</strong>
        <div className="event-context-actions">
          {onSyncTime && <button type="button" className="event-context-sync" onClick={onSyncTime} title="Set Dashboard time to this event">Sync time</button>}
          <button type="button" onClick={onClose} aria-label="Close event detail" title="Close event detail"><Icon name="close" size={16} /></button>
        </div>
      </div>
      <dl>
        <dt>Time</dt><dd>{formatEventTime(event.time)}</dd>
        <dt>Level</dt><dd>{event.level}</dd>
        <dt>Type</dt><dd>{event.type}</dd>
        <dt>Target</dt><dd>{event.targetLabel ?? event.proto ?? event.scope}</dd>
      </dl>
      {relatedEvent && onSelectRelated && <div className="event-context-related">
        <span>Go to related event</span>
        <button type="button" onClick={onSelectRelated} title="Go to related event" aria-label={`Go to related event: ${relatedEvent.message} · ${formatEventTime(relatedEvent.time)}`}><span className="event-context-related-message">{relatedEvent.message}</span><time className="event-context-related-time" dateTime={new Date(relatedEvent.time * 1000).toISOString()}>{formatEventTime(relatedEvent.time)}</time></button>
        {relatedOutsideRange && <small>Outside current range</small>}
      </div>}
      <p>{event.message}</p>
      {event.detail !== undefined && <pre>{JSON.stringify(event.detail, null, 2)}</pre>}
    </aside>
  );
}


function eventRelationFor(event: EventLogItem): EventRelation | null {
  const lifecycle = event.type.match(/^(stream|flow)_(detected|recovered|lost)$/);
  if (lifecycle) {
    const [, subject, action] = lifecycle;
    if (action === "lost") return { counterpartTypes: [`${subject}_detected`, `${subject}_recovered`], direction: "before" };
    return { counterpartTypes: [`${subject}_lost`], direction: "after" };
  }
  if (event.type.endsWith("_occurred")) return { counterpartTypes: [`${event.type.slice(0, -"occurred".length)}recovered`], direction: "after" };
  if (event.type.endsWith("_recovered")) return { counterpartTypes: [`${event.type.slice(0, -"recovered".length)}occurred`], direction: "before" };
  return null;
}

function findRelatedEvent(events: EventLogItem[], source: EventLogItem, relation: EventRelation) {
  return events.reduce<EventLogItem | null>((closest, candidate) => {
    if (candidate.id === source.id || !relation.counterpartTypes.includes(candidate.type) || !sameRelationTarget(source, candidate)) return closest;
    if (relation.direction === "before" ? candidate.time >= source.time : candidate.time <= source.time) return closest;
    if (!closest || Math.abs(candidate.time - source.time) < Math.abs(closest.time - source.time)) return candidate;
    return closest;
  }, null);
}

function sameRelationTarget(source: EventLogItem, candidate: EventLogItem) {
  if (source.flowKey || candidate.flowKey) return Boolean(source.flowKey && source.flowKey === candidate.flowKey);
  return Boolean(source.streamKey && source.streamKey === candidate.streamKey);
}

function closestEventWithin(events: EventLogItem[], selectedTimeSec: number | null) {
  if (selectedTimeSec === null) return null;
  return events.reduce<EventLogItem | null>((closest, event) => {
    const distance = Math.abs(event.time - selectedTimeSec);
    if (distance >= 0.5) return closest;
    if (!closest || distance < Math.abs(closest.time - selectedTimeSec)) return event;
    return closest;
  }, null);
}
export function parseEventColumnWidths(value: unknown): EventColumnWidths | undefined {
  let parsed = value;
  if (typeof value === "string") {
    try { parsed = JSON.parse(value); } catch { return undefined; }
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return undefined;
  const candidate = parsed as Partial<EventColumnWidths>;
  if (![candidate.time, candidate.level, candidate.target].every((width) => typeof width === "number" && Number.isFinite(width))) return undefined;
  return normalizeColumnWidths(candidate as EventColumnWidths);
}

function loadStoredColumnWidths() {
  try { return parseEventColumnWidths(window.localStorage.getItem(EVENT_LIST_STORAGE_KEY)) ?? DEFAULT_EVENT_COLUMN_WIDTHS; }
  catch { return DEFAULT_EVENT_COLUMN_WIDTHS; }
}

function normalizeColumnWidths(widths: EventColumnWidths) {
  return {
    time: clamp(widths.time, EVENT_COLUMN_LIMITS.time.min, EVENT_COLUMN_LIMITS.time.max),
    level: clamp(widths.level, EVENT_COLUMN_LIMITS.level.min, EVENT_COLUMN_LIMITS.level.max),
    target: clamp(widths.target, EVENT_COLUMN_LIMITS.target.min, EVENT_COLUMN_LIMITS.target.max)
  };
}

function fitColumnWidths(widths: EventColumnWidths, frameWidth: number): EventColumnWidths {
  if (frameWidth <= 0) return widths;
  const messageMinimum = Math.min(MIN_MESSAGE_COLUMN_PX, Math.max(48, Math.floor(frameWidth * 0.25)));
  const available = Math.max(0, frameWidth - EVENT_ROW_SIDE_PADDING_PX * 2 - EVENT_COLUMN_GAP_PX * 3 - messageMinimum);
  const minimum = Object.fromEntries((Object.keys(EVENT_COLUMN_LIMITS) as EventColumn[]).map((column) => [column, EVENT_COLUMN_LIMITS[column].min])) as EventColumnWidths;
  const next = { ...widths };
  let excess = next.time + next.level + next.target - available;
  for (const column of ["time", "level", "target"] as EventColumn[]) {
    if (excess <= 0) break;
    const reduction = Math.min(excess, Math.max(0, next[column] - minimum[column]));
    next[column] -= reduction;
    excess -= reduction;
  }
  if (excess <= 0) return next;
  const minimumTotal = minimum.time + minimum.level + minimum.target;
  const scale = minimumTotal > 0 ? available / minimumTotal : 0;
  return { time: minimum.time * scale, level: minimum.level * scale, target: minimum.target * scale };
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, Math.round(value)));
}

function eventColumnText(event: EventLogItem, column: EventColumn) {
  if (column === "time") return formatEventTime(event.time);
  if (column === "level") return event.level;
  return event.targetLabel ?? event.proto ?? event.scope;
}

function formatEventTime(epochSec: number) {
  const date = new Date(epochSec * 1000);
  const pad = (value: number, width = 2) => String(value).padStart(width, "0");
  return `${date.getFullYear()}/${pad(date.getMonth() + 1)}/${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}.${pad(date.getMilliseconds(), 3)}`;
}

function eventMatches(event: EventLogItem, query: string) {
  return matchesSearch([
    formatEventTime(event.time), event.level, event.type, event.scope, event.proto,
    event.interfaceId, event.streamKey, event.flowKey, event.targetLabel, event.message
  ], query);
}
