      {total === null ? <span>#{anchors[0].number} · Shift+click another event</span> : <span>#{anchors[0].number} → #{anchors[anchors.length - 1].number} · Δ {formatDuration(total)}</span>}
      <button type="button" onClick={onClear}>Clear</button>
    </div>
    {anchors.length > 1 && <ol className="event-measurement-segments">
      {anchors.slice(1).map((anchor, index) => {
        const previous = anchors[index];
        return <li key={anchor.event.id} title={`${formatEventTime(previous.event.time)} → ${formatEventTime(anchor.event.time)} `}>
          <span>#{previous.number} {formatEventAnchorLabel(previous.event)} → #{anchor.number} {formatEventAnchorLabel(anchor.event)}</span>
          <strong>Δ {formatDuration(anchor.event.time - previous.event.time)}</strong>
        </li>;
      })}
    </ol>}
  </section>;
}
